(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-963":{scenario:{company:"Song Lam Power Distribution",supervisor:{name:"Bùi Quốc Trung",role:{vi:"Điều độ viên trưởng ca",en:"Shift Control Supervisor"}},ref_code:"DMS-472-1104",title:{vi:"Khoanh đúng đoạn sự cố. Chuyển tải trong giới hạn. An toàn trước tiên.",en:"Isolate the right section. Transfer within limits. Safety first."},brief:{vi:"Tuyến 22 kV số 472 cắt máy cắt đầu tuyến sau khi tự đóng lại không thành công. Bạn lập phiếu thao tác DMS-472-1104: xác định đoạn sự cố theo chỉ báo sự cố (FPI), cô lập, cấp điện lại đầu tuyến và chuyển phần hạ lưu sang tuyến 474 qua dao liên lạc. Phụ tải trước sự cố: S12-15 60 A, S15-18 85 A, S18-21 55 A; tuyến 474 đang mang 210 A, giới hạn 380 A (mô phỏng). Sửa đoạn sự cố và dòng tuyến 474 sau chuyển tải, rồi lập báo cáo có căn cứ.",en:"Feeder 472 (22 kV) tripped at the source breaker after failed auto-reclosing. Prepare switching order DMS-472-1104: locate the faulted section from the fault passage indicators (FPI), isolate it, restore the upstream part and move the downstream part to feeder 474 via the tie switch. Pre-fault loads: S12-15 60 A, S15-18 85 A, S18-21 55 A; feeder 474 carries 210 A, limit 380 A (training data). Correct the faulted section and feeder 474 current after transfer, then write an evidence-based report."},reference_title:{vi:"Bản ghi FPI & sơ đồ phụ tải đã xác nhận · Tuyến 472",en:"Confirmed FPI record & load diagram · Feeder 472"},fields:[{id:"FAULT_SEG",label:{vi:"Đoạn sự cố cần cô lập",en:"Faulted section to isolate"},initial:"S15-18",expected:"S12-15",choices:["S09-12","S12-15","S15-18"],reference:"Bản ghi chỉ báo sự cố FPI",hint:{vi:"Sự cố nằm giữa FPI cuối cùng có dòng sự cố đi qua và FPI đầu tiên không ghi nhận dòng sự cố.",en:"The fault lies between the last FPI that saw fault current and the first FPI that did not."}},{id:"F474_AMP",label:{vi:"Dòng tuyến 474 sau chuyển tải (A)",en:"Feeder 474 current after transfer (A)"},initial:"410",expected:"350",reference:"Sơ đồ phụ tải trước sự cố",ref_value:{vi:"Tuyến 474 đang 210 A; S12-15 60 A; S15-18 85 A; S18-21 55 A",en:"Feeder 474 at 210 A; S12-15 60 A; S15-18 85 A; S18-21 55 A"},hint:{vi:"Đoạn sự cố đã cô lập không được cấp điện nên không cộng vào phụ tải chuyển sang tuyến 474.",en:"The isolated faulted section stays de-energised, so its load is not transferred to feeder 474."}}],sop32:{vi:"Dòng tuyến nhận = dòng hiện tại + tổng phụ tải các đoạn hạ lưu sau điểm cô lập (không gồm đoạn sự cố); chỉ đóng dao liên lạc khi kết quả không vượt giới hạn mang tải.",en:"Receiving feeder current = present current + loads of downstream sections beyond the isolation point (excluding the faulted section); close the tie only if the result stays within the limit."},context:{label:"DMS-SCADA / F472",metrics:[{label:{vi:"Tuyến 474 hiện tại",en:"Feeder 474 now"},value:"210 A"},{label:{vi:"Giới hạn tuyến 474",en:"Feeder 474 limit"},value:"380 A"},{label:{vi:"Cấp điện áp",en:"Voltage level"},value:"22 kV"}]},crisis:{vi:"Đội trưởng sửa chữa gọi: “Cho anh em leo cột làm luôn cho nhanh, phiếu công tác với tiếp địa tính sau. Khu công nghiệp đang gọi phàn nàn liên tục.”",en:"The repair crew leader calls: “Let the lads climb and start now, the work permit and earthing can come later. The industrial park keeps calling to complain.”"},options:{safe:{vi:"Không cho làm việc khi chưa cắt điện, kiểm tra không còn điện, đặt tiếp địa và cấp phiếu công tác; báo điều độ viên trưởng ca; trong lúc chờ, chuyển tải hạ lưu sang tuyến 474 để giảm khách hàng mất điện.",en:"Allow no work until the section is switched out, proven dead, earthed and covered by a work permit; inform the shift supervisor; meanwhile transfer the downstream load to feeder 474 to cut outage numbers."},shortcut:{vi:"Cho đội leo cột sửa ngay, bổ sung phiếu công tác và tiếp địa sau khi xong việc.",en:"Let the crew climb and repair now and add the permit and earthing afterwards."},wait:{vi:"Không trả lời đội sửa chữa và chờ lãnh đạo tự quyết định.",en:"Do not answer the crew and wait for management to decide."}},questions:{vi:["Vì sao đoạn sự cố là S12-15 và tuyến 474 sau chuyển tải là 350 A? Dữ liệu nào trong terminal chứng minh?","Trình bày trình tự biện pháp an toàn bắt buộc trước khi cho đội sửa chữa làm việc trên đoạn S12-15."],en:["Why is the faulted section S12-15 and why is feeder 474 at 350 A after transfer? Which terminal data proves it?","Set out the mandatory safety sequence before the repair crew may work on section S12-15."]},hints:{vi:["Chạy cat fpi.log và tìm ranh giới giữa FPI có dòng sự cố và FPI không ghi nhận.","Chỉ cộng các đoạn hạ lưu được cấp điện lại qua dao liên lạc vào dòng tuyến 474 theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không làm việc trên lưới khi chưa đủ biện pháp an toàn và phiếu công tác."],en:["Run cat fpi.log and find the boundary between FPIs that saw fault current and those that did not.","Add only the downstream sections re-energised via the tie switch to feeder 474 as in SOP 3.2.","Re-read SOP 4.2: no work on the network without full safety measures and a work permit."]},terminal:{system:"dms-scada",settable:["FAULT_SEG","F474_AMP"],commands:[{cmd:"status",out:{vi:"Tuyến 472: máy cắt đầu tuyến mở sau tự đóng lại không thành · LBS-09, LBS-12, LBS-15, LBS-18 đang đóng · dao liên lạc TIE-472/474 mở",en:"Feeder 472: source breaker open after failed reclosing · LBS-09, LBS-12, LBS-15, LBS-18 closed · tie switch TIE-472/474 open"}},{cmd:"cat fpi.log",out:{vi:"FPI-09: có dòng sự cố · FPI-12: có dòng sự cố · FPI-15: không ghi nhận · FPI-18: không ghi nhận",en:"FPI-09: fault current seen · FPI-12: fault current seen · FPI-15: none · FPI-18: none"}},{cmd:"cat load.txt",out:{vi:"Phụ tải trước sự cố: S12-15 = 60 A · S15-18 = 85 A · S18-21 (cuối tuyến) = 55 A",en:"Pre-fault loads: S12-15 = 60 A · S15-18 = 85 A · S18-21 (feeder end) = 55 A"}},{cmd:"cat feeder474.txt",out:{vi:"Tuyến 474: dòng hiện tại 210 A · giới hạn mang tải cho phép 380 A (mô phỏng) · điện áp cuối tuyến trong giới hạn",en:"Feeder 474: present current 210 A · permitted loading limit 380 A (training data) · end-of-feeder voltage within limits"}},{cmd:"cat crew.log",out:{vi:"Đội sửa chữa đã đến cột 472/14 · chưa có phiếu công tác · chưa đặt tiếp địa di động",en:"Repair crew at pole 472/14 · no work permit issued · portable earths not yet applied"}}]}},learning:{summary:{vi:"Kỹ sư vận hành lưới điện phân phối giám sát và điều khiển lưới trung, hạ áp qua hệ thống SCADA/DMS: thao tác đóng cắt, xử lý sự cố, cô lập và khôi phục cấp điện, điều chỉnh điện áp, phối hợp đội sửa chữa. Nghề quyết định độ tin cậy cung cấp điện (SAIDI, SAIFI) và an toàn của người làm việc trên lưới; đòi hỏi hiểu sơ đồ lưới, rơ le bảo vệ, tính toán phụ tải và kỷ luật quy trình tuyệt đối.",en:"A power distribution network operator monitors and controls the medium and low voltage network through SCADA/DMS: switching, fault handling, isolation and restoration, voltage control and coordination of repair crews. The role drives supply reliability (SAIDI, SAIFI) and the safety of people working on the network; it requires network diagrams, protection relays, load calculations and absolute procedural discipline."},responsibilities:{vi:["Giám sát trạng thái lưới, phụ tải, điện áp trên SCADA/DMS theo ca.","Lập và thực hiện phiếu thao tác đóng cắt theo kế hoạch và khi có sự cố.","Xác định vị trí sự cố, cô lập đoạn hỏng và khôi phục cấp điện cho phần còn lại.","Cấp phép, phối hợp và giám sát biện pháp an toàn cho đội công tác trên lưới.","Ghi nhật ký vận hành, thống kê sự cố và chỉ số độ tin cậy cung cấp điện."],en:["Monitor network status, load and voltage on SCADA/DMS each shift.","Prepare and execute switching orders for planned work and faults.","Locate faults, isolate damaged sections and restore supply to the rest.","Issue permits and coordinate and supervise safety measures for field crews.","Keep the operating log and track faults and reliability indices."]},competencies:[{name:{vi:"Đọc sơ đồ & SCADA",en:"Diagrams & SCADA"},desc:{vi:"Đọc nhanh sơ đồ một sợi, trạng thái thiết bị và cảnh báo trên màn hình điều độ.",en:"Read single-line diagrams, device states and alarms on the control screen quickly."}},{name:{vi:"Xử lý sự cố & khôi phục",en:"Fault handling & restoration"},desc:{vi:"Dùng FPI, rơ le và recloser để khoanh vùng sự cố, khôi phục điện nhanh và an toàn.",en:"Use FPIs, relays and reclosers to locate faults and restore supply quickly and safely."}},{name:{vi:"Tính toán phụ tải & điện áp",en:"Load & voltage calculation"},desc:{vi:"Kiểm tra giới hạn mang tải, sụt áp trước khi chuyển tải giữa các tuyến.",en:"Check loading limits and voltage drop before transferring load between feeders."}},{name:{vi:"An toàn điện",en:"Electrical safety"},desc:{vi:"Thực hiện đúng trình tự cắt điện, kiểm tra không điện, tiếp địa, rào chắn, biển báo.",en:"Apply the sequence: switch out, prove dead, earth, barrier and sign."}},{name:{vi:"Giao tiếp điều độ",en:"Control room communication"},desc:{vi:"Ra lệnh rõ ràng, nhắc lại lệnh, ghi âm và ghi nhật ký đầy đủ.",en:"Give clear instructions, use repeat-back, record calls and keep full logs."}}],knowledge:{vi:["Luật Điện lực và quy định hiện hành về vận hành hệ thống điện phân phối.","Quy định hiện hành của Bộ Công Thương về an toàn điện: cắt điện, kiểm tra không còn điện, tiếp địa, rào chắn, biển báo.","Chỉ số độ tin cậy SAIDI, SAIFI, MAIFI theo IEEE 1366.","Tự động hóa lưới phân phối: FLISR, recloser, dao phụ tải, chỉ báo sự cố (FPI).","IEC 61850 về truyền thông trong trạm biến áp và tự động hóa lưới."],en:["The Electricity Law and current rules on distribution system operation.","Current Ministry of Industry and Trade electrical safety rules: switching out, proving dead, earthing, barriers and signs.","Reliability indices SAIDI, SAIFI and MAIFI under IEEE 1366.","Distribution automation: FLISR, reclosers, load break switches and fault passage indicators (FPI).","IEC 61850 on substation communication and network automation."]},tools:["Hệ thống SCADA/DMS","Sơ đồ một sợi lưới phân phối","Phần mềm tính toán trào lưu công suất","Hệ thống quản lý mất điện (OMS)","Thiết bị kiểm tra không còn điện"],kpis:{vi:["SAIDI, SAIFI của khu vực phụ trách so với mục tiêu.","Thời gian khôi phục điện trung bình cho phần lưới không sự cố.","Số thao tác nhầm, vi phạm an toàn (mục tiêu bằng 0).","Tỷ lệ phiếu thao tác lập đúng, đủ ngay lần đầu."],en:["SAIDI and SAIFI for the area versus target.","Average restoration time for healthy network sections.","Switching errors and safety violations (target zero).","Share of switching orders correct and complete first time."]},day:[{time:"06:45",vi:"Nhận ca, đọc nhật ký vận hành và danh sách phiếu công tác đang mở.",en:"Take over the shift and read the operating log and open work permits."},{time:"08:00",vi:"Thực hiện thao tác cắt điện theo kế hoạch bảo trì tuyến.",en:"Carry out planned switching for feeder maintenance."},{time:"10:30",vi:"Xử lý sự cố tuyến: khoanh vùng theo FPI, cô lập và khôi phục cấp điện.",en:"Handle a feeder fault: locate by FPI, isolate and restore supply."},{time:"14:00",vi:"Cấp phép và giám sát biện pháp an toàn cho đội công tác trên lưới.",en:"Issue permits and supervise safety measures for crews on the network."},{time:"18:00",vi:"Bàn giao ca, cập nhật thống kê sự cố và chỉ số độ tin cậy.",en:"Hand over the shift and update fault statistics and reliability indices."}],mistakes:{vi:["Đọc sai chỉ báo sự cố, cô lập nhầm đoạn lưới và đóng điện vào điểm sự cố.","Cộng cả phụ tải đoạn sự cố khi tính chuyển tải, bỏ lỡ cơ hội khôi phục điện.","Cho phép làm việc khi chưa tiếp địa, chưa có phiếu công tác vì áp lực thời gian."],en:["Misreading fault indicators, isolating the wrong section and re-energising onto the fault.","Including the faulted section's load in the transfer check and missing a chance to restore supply.","Allowing work before earthing and a work permit because of time pressure."]},career:[{vi:"Nhân viên trực vận hành trạm biến áp",en:"Substation operator"},{vi:"Điều độ viên lưới điện phân phối",en:"Distribution network controller"},{vi:"Điều độ viên trưởng ca",en:"Shift control supervisor"},{vi:"Trưởng phòng điều độ",en:"Head of network control"}],glossary:[{term:"SCADA/DMS",vi:"Hệ thống giám sát, điều khiển và quản lý lưới phân phối từ trung tâm điều độ.",en:"Supervisory control and distribution management system run from the control centre."},{term:"FPI",vi:"Chỉ báo sự cố: thiết bị trên đường dây báo có dòng sự cố đi qua vị trí đặt.",en:"Fault passage indicator: a line device showing that fault current passed its location."},{term:"Recloser",vi:"Thiết bị tự đóng lại: tự cắt khi sự cố và đóng lại để loại trừ sự cố thoáng qua.",en:"Device that trips on a fault and recloses to clear transient faults."},{term:"SAIDI",vi:"Thời gian mất điện trung bình của một khách hàng trong kỳ báo cáo.",en:"Average outage duration per customer over the reporting period."},{term:"Phiếu công tác",vi:"Văn bản cho phép làm việc trên thiết bị điện, ghi rõ phạm vi và biện pháp an toàn.",en:"Work permit authorising work on electrical equipment with defined scope and safety measures."}],quiz:[{q:{vi:"FPI-06 và FPI-09 ghi nhận dòng sự cố, FPI-12 thì không. Sự cố nằm ở đâu?",en:"FPI-06 and FPI-09 saw fault current, FPI-12 did not. Where is the fault?"},options:{vi:["Giữa FPI-06 và FPI-09","Giữa FPI-09 và FPI-12","Sau FPI-12","Trước FPI-06"],en:["Between FPI-06 and FPI-09","Between FPI-09 and FPI-12","Beyond FPI-12","Before FPI-06"]},answer:1,explain:{vi:"Sự cố nằm sau FPI cuối cùng có dòng sự cố (FPI-09) và trước FPI đầu tiên không ghi nhận (FPI-12).",en:"The fault is beyond the last FPI with fault current (FPI-09) and before the first without it (FPI-12)."}},{q:{vi:"Tuyến nhận đang 200 A, giới hạn 350 A; cần chuyển hai đoạn hạ lưu 70 A và 60 A. Dòng sau chuyển tải là bao nhiêu?",en:"The receiving feeder carries 200 A with a 350 A limit; two downstream sections of 70 A and 60 A are transferred. What is the new current?"},options:{vi:["200 A","350 A","330 A","130 A"],en:["200 A","350 A","330 A","130 A"]},answer:2,explain:{vi:"Dòng sau chuyển tải = 200 + 70 + 60 = 330 A, vẫn dưới giới hạn 350 A.",en:"New current = 200 + 70 + 60 = 330 A, still below the 350 A limit."}},{q:{vi:"Đội sửa chữa muốn làm việc ngay khi chưa tiếp địa. Bạn làm gì?",en:"The repair crew wants to start before earthing. What do you do?"},options:{vi:["Đồng ý nếu máy cắt đã mở","Yêu cầu làm nhanh","Không trả lời","Không cấp phép đến khi đủ biện pháp an toàn và phiếu công tác"],en:["Agree if the breaker is open","Tell them to be quick","Do not answer","No permit until all safety measures and the work permit are in place"]},answer:3,explain:{vi:"Điện áp cảm ứng, đóng nhầm hoặc nguồn ngược có thể gây chết người; tiếp địa và phiếu công tác là bắt buộc.",en:"Induced voltage, wrong switching or backfeed can kill; earthing and a work permit are mandatory."}},{q:{vi:"SAIDI đo lường điều gì?",en:"What does SAIDI measure?"},options:{vi:["Thời gian mất điện trung bình của một khách hàng trong kỳ","Số lần mất điện thoáng qua","Tổn thất điện năng","Điện áp trung bình"],en:["Average outage duration per customer in the period","Number of momentary interruptions","Energy losses","Average voltage"]},answer:0,explain:{vi:"SAIDI bằng tổng số phút mất điện của khách hàng chia cho tổng số khách hàng được phục vụ.",en:"SAIDI equals total customer interruption minutes divided by total customers served."}}]}},"KK-964":{scenario:{company:"Lumora Building Energy",supervisor:{name:"Tạ Quang Vĩnh",role:{vi:"Trưởng nhóm Kiểm toán Năng lượng",en:"Energy Audit Lead"}},ref_code:"MV-6412",title:{vi:"Nền đúng thời tiết. Tiết kiệm đúng số đo.",en:"Weather-true baseline. Metered savings."},brief:{vi:"Bạn kiểm tra báo cáo đo lường và kiểm chứng (M&V) MV-6412 cho giải pháp ECM-07: lắp biến tần và tối ưu điều khiển cụm chiller của một tòa văn phòng. Công tơ riêng đo liên tục toàn bộ cụm chiller; tiết kiệm dự kiến chỉ khoảng 6% điện toàn tòa. Mô hình nền: E = 42000 + 180 x CDD (kWh/tháng). Tháng 10: CDD = 260, điện cụm chiller đo được 71500 kWh. Sửa phương án IPMVP và số kWh tiết kiệm trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are reviewing measurement and verification (M&V) report MV-6412 for ECM-07: variable speed drives and optimized controls on an office tower chiller plant. A dedicated meter continuously logs the whole chiller plant; expected savings are only about 6% of building electricity. Baseline model: E = 42000 + 180 x CDD (kWh/month). October: CDD = 260, metered chiller plant use 71500 kWh. Correct the IPMVP option and the kWh savings in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Kế hoạch M&V đã phê duyệt · MV-6412",en:"Approved M&V plan · MV-6412"},fields:[{id:"MV_OPTION",label:{vi:"Phương án M&V theo IPMVP",en:"IPMVP M&V option"},initial:"IPMVP-C",expected:"IPMVP-B",choices:["IPMVP-A","IPMVP-B","IPMVP-C"],reference:"Kế hoạch M&V đã phê duyệt",hint:{vi:"Ranh giới đo bao trùm cụm chiller và mọi thông số được đo liên tục; tiết kiệm nhỏ so với công tơ tổng thì khó tách bằng phương án toàn tòa.",en:"The boundary covers the chiller plant with every parameter metered continuously; small savings are hard to isolate on the whole-building meter."}},{id:"SAVED_KWH",label:{vi:"Điện năng tiết kiệm tháng 10 (kWh)",en:"October energy savings (kWh)"},initial:"10500",expected:"17300",reference:"Bảng tính tiết kiệm M&V",ref_value:{vi:"Nền E = 42000 + 180 x CDD; CDD tháng 10 = 260; đo được 71500 kWh",en:"Baseline E = 42000 + 180 x CDD; October CDD = 260; metered 71500 kWh"},hint:{vi:"So sánh với nền đã hiệu chỉnh theo thời tiết của chính kỳ báo cáo, không so với số đo thô của năm trước.",en:"Compare with the weather-adjusted baseline of the reporting period itself, not with last year's raw reading."}}],sop32:{vi:"Tiết kiệm (kWh) = nền hiệu chỉnh - tiêu thụ đo được của kỳ báo cáo; nền hiệu chỉnh = 42000 + 180 x CDD của chính kỳ báo cáo (điều chỉnh thường xuyên theo IPMVP).",en:"Savings (kWh) = adjusted baseline - metered use in the reporting period; adjusted baseline = 42000 + 180 x CDD of that same period (IPMVP routine adjustment)."},context:{label:"EMS / MV-6412",metrics:[{label:{vi:"CDD tháng 10",en:"October CDD"},value:"260"},{label:{vi:"Điện cụm chiller đo được",en:"Metered chiller plant use"},value:"71,500 kWh"},{label:{vi:"Mô hình nền (kWh/tháng)",en:"Baseline model (kWh/month)"},value:"42000 + 180 x CDD"}]},crisis:{vi:"Đại diện ESCO nhắn: “Hợp đồng cam kết tiết kiệm 25%, cứ lấy tháng nóng nhất năm ngoái làm nền và ghi phương án C cho gọn, chủ đầu tư không soi đâu. Cần ký nghiệm thu để thanh toán đợt 2 trong tuần này.”",en:"The ESCO representative messages you: “The contract promises 25% savings, just use last year's hottest month as the baseline and write Option C to keep it simple, the owner will not check. We need sign-off for the second payment this week.”"},options:{safe:{vi:"Giữ phương án IPMVP-B, tính tiết kiệm trên nền hiệu chỉnh theo CDD, nêu rõ độ bất định và báo trưởng nhóm; đề xuất họp ba bên rà soát cam kết hợp đồng bằng số liệu đo.",en:"Keep IPMVP-B, compute savings on the CDD-adjusted baseline, state the uncertainty and inform the lead; propose a three-party review of the contract commitment using metered data."},shortcut:{vi:"Lấy tháng nóng nhất năm ngoái làm nền để đạt 25% và ký nghiệm thu cho kịp đợt thanh toán.",en:"Use last year's hottest month as the baseline to reach 25% and sign off in time for the payment."},wait:{vi:"Gác báo cáo lại, chờ ESCO và chủ đầu tư tự thống nhất con số tiết kiệm.",en:"Shelve the report and wait for the ESCO and the owner to agree on a savings figure."}},questions:{vi:["Vì sao chọn IPMVP-B thay vì IPMVP-C? Dữ liệu công tơ nào chứng minh lựa chọn của bạn?","Trình bày cách hiệu chỉnh nền theo CDD và rủi ro nếu so sánh với số đo thô của năm trước hoặc chọn kỳ nền có lợi."],en:["Why did you choose IPMVP-B instead of IPMVP-C? Which meter data supports your choice?","Explain how you adjusted the baseline for CDD and the risk of comparing with last year's raw reading or cherry-picking the baseline period."]},hints:{vi:["Chạy lệnh liệt kê công tơ để xác định ranh giới đo trước khi chọn phương án IPMVP.","Thay CDD của kỳ báo cáo vào mô hình nền ở SOP mục 3.2 rồi mới trừ số đo thực tế.","Đọc lại SOP mục 4.2: không chọn kỳ nền hay phương án đo để làm đẹp kết quả; báo cáo áp lực bằng văn bản."],en:["List the meters to confirm the measurement boundary before choosing the IPMVP option.","Plug the reporting-period CDD into the baseline model in SOP 3.2 before subtracting the metered use.","Re-read SOP 4.2: never pick a baseline period or M&V option to flatter results; report pressure in writing."]},terminal:{system:"ems-mv",settable:["MV_OPTION","SAVED_KWH"],commands:[{cmd:"meter list",out:{vi:"M-CH01: công tơ riêng cụm chiller (máy làm lạnh, bơm, tháp giải nhiệt), ghi liên tục chu kỳ 15 phút. M-MAIN: công tơ tổng tòa nhà.",en:"M-CH01: dedicated chiller plant meter (chillers, pumps, cooling towers), continuous 15-minute logging. M-MAIN: building main meter."}},{cmd:"cat baseline.txt",out:{vi:"Mô hình nền 12 tháng năm 2025: E = 42000 + 180 x CDD (kWh/tháng), R2 = 0.93, CV(RMSE) = 8.1%.",en:"12-month 2025 baseline model: E = 42000 + 180 x CDD (kWh/month), R2 = 0.93, CV(RMSE) = 8.1%."}},{cmd:"trend m-ch01 2026-10",out:{vi:"Tháng 10/2026: điện cụm chiller đo được 71500 kWh. Tháng 10/2025: 82000 kWh.",en:"October 2026: metered chiller plant use 71500 kWh. October 2025: 82000 kWh."}},{cmd:"weather cdd",out:{vi:"CDD nhiệt độ gốc 18°C: tháng 10/2025 = 228, tháng 10/2026 = 260 (trạm khí tượng gần nhất).",en:"CDD at 18°C base: October 2025 = 228, October 2026 = 260 (nearest weather station)."}}]}},learning:{summary:{vi:"Kỹ sư hiệu quả năng lượng tòa nhà kiểm toán năng lượng, mô phỏng và đề xuất giải pháp tiết kiệm (ECM) cho điều hòa thông gió, chiếu sáng, bơm và vỏ công trình, rồi đo lường và kiểm chứng (M&V) mức tiết kiệm thực tế. Công việc đòi hỏi vững nhiệt lạnh, điện, dữ liệu BMS, quy chuẩn công trình sử dụng năng lượng hiệu quả và trung thực tuyệt đối với số liệu đo.",en:"A building energy efficiency engineer audits energy use, models and proposes energy conservation measures (ECM) for HVAC, lighting, pumps and the building envelope, then measures and verifies (M&V) the actual savings. The role requires strong HVAC, electrical and BMS data skills, knowledge of energy-efficient building codes and strict honesty with metered data."},responsibilities:{vi:["Thực hiện kiểm toán năng lượng: thu thập hóa đơn, đo đạc hiện trường và lập cân bằng năng lượng theo hệ thống.","Xây dựng đường cơ sở năng lượng và chỉ số hiệu suất (EnPI) có hiệu chỉnh theo thời tiết và mức sử dụng.","Đề xuất và tính hiệu quả kinh tế các giải pháp ECM: chiller, biến tần, LED, điều khiển BMS, vỏ bao che.","Lập kế hoạch M&V, chọn phương án IPMVP, giám sát lắp công tơ và tính tiết kiệm định kỳ.","Hỗ trợ tuân thủ QCVN 09:2017/BXD, báo cáo năng lượng định kỳ và hệ thống quản lý năng lượng ISO 50001."],en:["Run energy audits: collect bills, take field measurements and build a system-level energy balance.","Build energy baselines and performance indicators (EnPI) adjusted for weather and occupancy.","Propose ECMs and assess their economics: chillers, drives, LED, BMS controls and envelope upgrades.","Write M&V plans, choose the IPMVP option, supervise meter installation and calculate periodic savings.","Support compliance with QCVN 09:2017/BXD, periodic energy reporting and an ISO 50001 energy management system."]},competencies:[{name:{vi:"Kiểm toán năng lượng",en:"Energy auditing"},desc:{vi:"Đo đạc, phân tách tiêu thụ theo hệ thống và tìm cơ hội tiết kiệm có căn cứ số liệu.",en:"Measure, break down consumption by system and find data-backed savings opportunities."}},{name:{vi:"Mô hình hóa & thống kê",en:"Modeling & statistics"},desc:{vi:"Lập hồi quy theo CDD, đánh giá R2, CV(RMSE) và mô phỏng năng lượng tòa nhà.",en:"Build CDD regressions, assess R2 and CV(RMSE) and run building energy simulations."}},{name:{vi:"HVAC & điều khiển",en:"HVAC & controls"},desc:{vi:"Hiểu cụm chiller, bơm, tháp giải nhiệt, AHU và chiến lược điều khiển trên BMS.",en:"Understand chiller plants, pumps, cooling towers, AHUs and BMS control strategies."}},{name:{vi:"Phân tích kinh tế",en:"Economic analysis"},desc:{vi:"Tính thời gian hoàn vốn, NPV, chi phí vòng đời và rủi ro của từng giải pháp.",en:"Calculate payback, NPV, life-cycle cost and risk for each measure."}},{name:{vi:"Liêm chính số liệu",en:"Data integrity"},desc:{vi:"Không chọn kỳ nền hay phương pháp để làm đẹp kết quả; công bố độ bất định.",en:"Never cherry-pick baselines or methods to flatter results; disclose uncertainty."}}],knowledge:{vi:["Luật Sử dụng năng lượng tiết kiệm và hiệu quả số 50/2010/QH12 và các văn bản sửa đổi, hướng dẫn.","QCVN 09:2017/BXD về các công trình xây dựng sử dụng năng lượng hiệu quả: vỏ công trình, HVAC, chiếu sáng.","IPMVP: bốn phương án A, B, C, D, ranh giới đo, điều chỉnh thường xuyên và không thường xuyên.","ISO 50001 (hệ thống quản lý năng lượng), ISO 50002 (kiểm toán năng lượng) và ISO 50006 (đường cơ sở, EnPI).","ASHRAE 90.1 và ASHRAE Guideline 14 về đo lường tiết kiệm và tiêu chí đánh giá mô hình."],en:["Law on Economical and Efficient Use of Energy No. 50/2010/QH12 and its amendments and guidance.","QCVN 09:2017/BXD on energy-efficient buildings: envelope, HVAC and lighting.","IPMVP: options A, B, C and D, measurement boundary, routine and non-routine adjustments.","ISO 50001 (energy management systems), ISO 50002 (energy audits) and ISO 50006 (baselines, EnPI).","ASHRAE 90.1 and ASHRAE Guideline 14 on savings measurement and model acceptance criteria."]},tools:["Hệ thống quản lý tòa nhà (BMS)","Phần mềm mô phỏng năng lượng (EnergyPlus)","Công tơ và bộ ghi dữ liệu di động","Camera nhiệt","Đồng hồ đo lưu lượng siêu âm","Bảng tính hồi quy"],kpis:{vi:["Điện năng tiết kiệm đã kiểm chứng so với cam kết (kWh/năm).","Cường độ sử dụng năng lượng EUI (kWh/m2/năm) của tòa nhà.","Mô hình nền đạt tiêu chí thống kê (R2, CV(RMSE)) đã thống nhất.","Thời gian hoàn vốn thực tế so với dự kiến của các ECM."],en:["Verified energy savings versus commitment (kWh/year).","Building energy use intensity EUI (kWh/m2/year).","Baseline models meeting the agreed statistical criteria (R2, CV(RMSE)).","Actual versus planned payback of the ECMs."]},day:[{time:"08:00",vi:"Xem cảnh báo EMS, so sánh tải chiller đêm qua với ngày có thời tiết tương đương.",en:"Check EMS alarms and compare last night's chiller load with a weather-matched day."},{time:"09:30",vi:"Đo hiện trường: công suất bơm, nhiệt độ nước lạnh vào ra, lưu lượng siêu âm.",en:"Field measurements: pump power, chilled water supply and return temperatures, ultrasonic flow."},{time:"13:30",vi:"Cập nhật mô hình hồi quy nền và tính tiết kiệm tháng theo kế hoạch M&V.",en:"Update the baseline regression and calculate monthly savings per the M&V plan."},{time:"15:30",vi:"Họp với ESCO và ban quản lý tòa nhà về kết quả và điều chỉnh không thường xuyên.",en:"Meet the ESCO and facility team on results and non-routine adjustments."},{time:"17:00",vi:"Hoàn thiện báo cáo M&V, lưu dữ liệu thô và nhật ký giả định.",en:"Finish the M&V report and archive raw data and the assumptions log."}],mistakes:{vi:["So sánh với số đo cùng kỳ năm trước mà không hiệu chỉnh theo thời tiết và mức sử dụng.","Chọn phương án C khi tiết kiệm nhỏ hơn mức dao động tự nhiên của công tơ tổng.","Nhầm kW/RT với COP hoặc tính hoàn vốn trên công suất danh định thay vì vận hành thực tế."],en:["Comparing with last year's reading without adjusting for weather and occupancy.","Choosing Option C when savings are smaller than the natural noise of the main meter.","Confusing kW/RT with COP or computing payback on nameplate power instead of actual operation."]},career:[{vi:"Kỹ thuật viên đo đạc năng lượng",en:"Energy metering technician"},{vi:"Kỹ sư kiểm toán năng lượng",en:"Energy audit engineer"},{vi:"Chuyên gia M&V và quản lý năng lượng",en:"M&V and energy management specialist"},{vi:"Giám đốc dịch vụ năng lượng (ESCO) / phát triển bền vững",en:"ESCO director / head of sustainability"}],glossary:[{term:"ECM",vi:"Giải pháp tiết kiệm năng lượng cụ thể, ví dụ lắp biến tần hay thay chiller hiệu suất cao.",en:"A specific energy conservation measure, such as adding drives or replacing a chiller."},{term:"IPMVP",vi:"Nghị định thư quốc tế về đo lường và kiểm chứng hiệu quả, gồm các phương án A, B, C, D.",en:"International protocol for measuring and verifying performance, with options A, B, C and D."},{term:"CDD",vi:"Độ ngày làm lạnh: tổng phần nhiệt độ trung bình ngày vượt nhiệt độ gốc, đo nhu cầu làm lạnh.",en:"Cooling degree days: the sum of daily mean temperature above a base, a proxy for cooling demand."},{term:"EUI",vi:"Cường độ sử dụng năng lượng, tính bằng kWh trên mét vuông sàn mỗi năm.",en:"Energy use intensity, measured in kWh per square meter of floor area per year."},{term:"kW/RT",vi:"Điện năng tiêu thụ trên mỗi tấn lạnh; càng thấp thì cụm chiller càng hiệu quả.",en:"Electrical input per ton of refrigeration; the lower it is, the more efficient the plant."}],quiz:[{q:{vi:"Mô hình nền E = 30000 + 150 x CDD; kỳ báo cáo CDD = 200, đo được 52000 kWh. Tiết kiệm là bao nhiêu?",en:"Baseline E = 30000 + 150 x CDD; reporting CDD = 200, metered 52000 kWh. What are the savings?"},options:{vi:["8000 kWh","2000 kWh","60000 kWh","22000 kWh"],en:["8000 kWh","2000 kWh","60000 kWh","22000 kWh"]},answer:0,explain:{vi:"Nền hiệu chỉnh = 30000 + 150 x 200 = 60000 kWh; tiết kiệm = 60000 - 52000 = 8000 kWh.",en:"Adjusted baseline = 30000 + 150 x 200 = 60000 kWh; savings = 60000 - 52000 = 8000 kWh."}},{q:{vi:"Phương án IPMVP nào dựa trên mô phỏng đã hiệu chỉnh với số liệu đo?",en:"Which IPMVP option relies on a calibrated simulation?"},options:{vi:["Phương án A","Phương án B","Phương án C","Phương án D"],en:["Option A","Option B","Option C","Option D"]},answer:3,explain:{vi:"Phương án D dùng mô phỏng hiệu chỉnh khi không có hoặc không đủ số liệu đo nền.",en:"Option D uses calibrated simulation when baseline metering is missing or insufficient."}},{q:{vi:"ESCO đề nghị lấy tháng nóng nhất năm trước làm nền để đạt cam kết tiết kiệm. Bạn làm gì?",en:"The ESCO asks you to use last year's hottest month as the baseline to meet the savings commitment. What do you do?"},options:{vi:["Đồng ý vì hợp đồng đã ký","Chọn tháng mát nhất cho cân bằng","Giữ nền 12 tháng hiệu chỉnh thời tiết, báo cáo áp lực và đề xuất rà soát ba bên","Không báo cáo tháng này"],en:["Agree because the contract is signed","Pick the coolest month to balance it","Keep the 12-month weather-adjusted baseline, report the pressure and propose a three-party review","Skip this month's report"]},answer:2,explain:{vi:"Chọn kỳ nền có lợi là làm sai lệch kết quả M&V; phải giữ phương pháp đã phê duyệt và báo cáo minh bạch.",en:"Cherry-picking the baseline distorts M&V results; keep the approved method and report transparently."}},{q:{vi:"Hai cụm chiller cùng tải: cụm X 0.62 kW/RT, cụm Y 0.78 kW/RT. Nhận định nào đúng?",en:"Two chiller plants at the same load: X at 0.62 kW/RT, Y at 0.78 kW/RT. Which statement is correct?"},options:{vi:["Cụm Y hiệu quả hơn","Cụm X hiệu quả hơn","Hai cụm như nhau","Không so sánh được kW/RT"],en:["Plant Y is more efficient","Plant X is more efficient","They are equal","kW/RT cannot be compared"]},answer:1,explain:{vi:"kW/RT là điện năng trên một tấn lạnh, giá trị thấp hơn nghĩa là hiệu quả cao hơn.",en:"kW/RT is power per ton of cooling; a lower value means higher efficiency."}}]}},"KK-965":{scenario:{company:"Voltana Storage Systems",supervisor:{name:"Kiều Thanh Nhàn",role:{vi:"Trưởng phòng Kỹ thuật BESS",en:"BESS Engineering Manager"}},ref_code:"CF-3318",title:{vi:"Đúng hóa học cell. Đúng kWh giao lưới.",en:"Right cell chemistry. Right kWh to grid."},brief:{vi:"Bạn rà soát cấu hình nghiệm thu CF-3318 của hệ BESS-2 (2500 kWh DC) tại một nhà máy điện mặt trời. Datasheet cell ghi 3.2 V danh định, 280 Ah; cửa sổ SOC vận hành 10-90%; thử dung lượng tháng 9 cho SOH 95%; hiệu suất xả một chiều PCS và biến áp 95%. Sửa hồ sơ hóa học cell trong BMS và năng lượng xả khả dụng tại điểm đấu nối (POI) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are reviewing commissioning configuration CF-3318 for BESS-2 (2500 kWh DC) at a solar plant. The cell datasheet shows 3.2 V nominal, 280 Ah; the operating SOC window is 10-90%; the September capacity test gave SOH 95%; one-way PCS and transformer discharge efficiency is 95%. Correct the BMS cell chemistry profile and the usable discharge energy at the point of interconnection (POI) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Hồ sơ thiết kế & thử nghiệm đã duyệt · CF-3318",en:"Approved design & test file · CF-3318"},fields:[{id:"CELL_CHEM",label:{vi:"Hồ sơ hóa học cell trong BMS",en:"BMS cell chemistry profile"},initial:"NMC",expected:"LFP",choices:["NMC","LFP","LTO"],reference:"Datasheet cell và hồ sơ BMS",hint:{vi:"Điện áp danh định 3.2 V và ngưỡng nạp 3.65 V/cell khác hẳn mức 3.6-3.7 V danh định của NMC hay 2.3-2.4 V của LTO.",en:"A 3.2 V nominal cell with a 3.65 V charge limit is far from NMC at 3.6-3.7 V nominal or LTO at 2.3-2.4 V."}},{id:"USABLE_KWH",label:{vi:"Năng lượng xả khả dụng tại POI (kWh)",en:"Usable discharge energy at POI (kWh)"},initial:"2000",expected:"1805",reference:"Bảng tính năng lượng khả dụng",ref_value:{vi:"Danh định 2500 kWh DC; SOC 10-90%; SOH 95%; hiệu suất xả PCS + biến áp 95%",en:"Nameplate 2500 kWh DC; SOC 10-90%; SOH 95%; PCS + transformer discharge efficiency 95%"},hint:{vi:"Năng lượng tại điểm đấu nối phải trừ cả suy giảm dung lượng và tổn hao chuyển đổi, không chỉ cửa sổ SOC.",en:"Energy at the interconnection point must account for capacity fade and conversion losses, not just the SOC window."}}],sop32:{vi:"Năng lượng xả khả dụng tại POI (kWh) = dung lượng danh định DC x (SOCmax - SOCmin) x SOH x hiệu suất xả một chiều của PCS và biến áp.",en:"Usable discharge energy at POI (kWh) = DC nameplate capacity x (SOCmax - SOCmin) x SOH x one-way discharge efficiency of the PCS and transformer."},context:{label:"EMS / CF-3318",metrics:[{label:{vi:"Dung lượng danh định DC",en:"DC nameplate capacity"},value:"2,500 kWh"},{label:{vi:"Cửa sổ SOC",en:"SOC window"},value:"10-90%"},{label:{vi:"SOH thử tháng 9",en:"September test SOH"},value:"95%"},{label:{vi:"Hiệu suất xả PCS + biến áp",en:"PCS + transformer efficiency"},value:"95%"}]},crisis:{vi:"Quản lý dự án EPC nhắn: “Cứ để hồ sơ NMC, tắt tạm cảnh báo quá áp cell để chạy thử 72 giờ cho kịp ngày vận hành thương mại, xong rồi chỉnh sau. Chủ đầu tư phạt chậm tiến độ từng ngày đấy.”",en:"The EPC project manager messages you: “Leave the NMC profile, mute the cell overvoltage alarm and run the 72-hour test to hit the commercial operation date, we will fix it later. The owner charges delay penalties every day.”"},options:{safe:{vi:"Dừng nạp, nạp đúng hồ sơ LFP với ngưỡng 3.65 V/cell, giữ mọi liên động bảo vệ và báo giám đốc dự án cùng bộ phận an toàn; chạy thử lại sau khi kiểm tra rack R3.",en:"Stop charging, load the correct LFP profile with a 3.65 V/cell limit, keep every protection interlock and inform the project director and safety team; retest after inspecting rack R3."},shortcut:{vi:"Tắt cảnh báo quá áp để chạy đủ 72 giờ, sửa hồ sơ BMS sau ngày vận hành thương mại.",en:"Mute the overvoltage alarm to finish the 72 hours and fix the BMS profile after the commercial operation date."},wait:{vi:"Để hệ thống tiếp tục chạy thử và chờ nhà cung cấp BMS sang kiểm tra vào tuần sau.",en:"Let the test continue and wait for the BMS vendor to visit next week."}},questions:{vi:["Dữ liệu nào cho thấy cell là LFP, và hồ sơ NMC gây rủi ro gì cho ngưỡng nạp của BMS?","Trình bày cách tính năng lượng khả dụng tại POI và hậu quả nếu cam kết với bên mua điện theo con số 2000 kWh."],en:["Which data shows the cells are LFP, and what risk does the NMC profile create for the BMS charge limits?","Explain how you calculated usable energy at the POI and the consequence of committing 2000 kWh to the offtaker."]},hints:{vi:["Đọc thông tin rack và tệp cấu hình BMS, so điện áp danh định với ngưỡng đang cài.","Áp dụng đủ bốn thừa số ở SOP mục 3.2: dung lượng, cửa sổ SOC, SOH và hiệu suất xả.","Đọc lại SOP mục 4.2: không tắt hay bỏ qua bảo vệ pin để chạy kịp tiến độ; báo cáo người có thẩm quyền."],en:["Read the rack information and BMS config file, then compare nominal voltage with the configured limit.","Apply all four factors in SOP 3.2: capacity, SOC window, SOH and discharge efficiency.","Re-read SOP 4.2: never mute or bypass battery protection to meet a schedule; escalate to the responsible authority."]},terminal:{system:"bess-ems",settable:["CELL_CHEM","USABLE_KWH"],commands:[{cmd:"bms info",out:{vi:"Rack R1-R8: cell lăng trụ 3.2 V danh định, 280 Ah; dải làm việc của nhà sản xuất 2.5-3.65 V/cell.",en:"Racks R1-R8: prismatic cells 3.2 V nominal, 280 Ah; manufacturer operating range 2.5-3.65 V/cell."}},{cmd:"cat bms.cfg",out:{vi:"Tệp cấu hình hiện tại: chem_profile=NMC; v_cell_max=4.20; v_cell_min=3.00; soc_max=90; soc_min=10",en:"Current config file: chem_profile=NMC; v_cell_max=4.20; v_cell_min=3.00; soc_max=90; soc_min=10"}},{cmd:"alarm log",out:{vi:"Cảnh báo: cell R3-M07-C12 đạt 3.71 V khi nạp, BMS chưa ngắt vì ngưỡng đang cài là 4.20 V.",en:"Warning: cell R3-M07-C12 reached 3.71 V while charging; the BMS did not trip because the limit is set at 4.20 V."}},{cmd:"soh report",out:{vi:"Thử dung lượng 15/09/2026 ở 0.5C: SOH trung bình 95%, lệch giữa các rack 1.2%.",en:"Capacity test 15/09/2026 at 0.5C: average SOH 95%, rack-to-rack spread 1.2%."}},{cmd:"pcs status",out:{vi:"PCS 1000 kW; hiệu suất xả một chiều PCS + biến áp đo được 95% tại 75% tải; dung lượng danh định DC 2500 kWh.",en:"PCS 1000 kW; measured one-way PCS + transformer discharge efficiency 95% at 75% load; DC nameplate 2500 kWh."}}]}},learning:{summary:{vi:"Kỹ sư hệ thống lưu trữ năng lượng thiết kế, tích hợp, nghiệm thu và vận hành hệ BESS gồm cell, BMS, PCS, EMS và hệ thống an toàn cháy. Nghề này biến pin thành nguồn linh hoạt cho cắt đỉnh, dịch chuyển năng lượng tái tạo và điều tần, đòi hỏi hiểu điện hóa, điện tử công suất, đấu nối lưới và kỷ luật an toàn với rủi ro thoát nhiệt.",en:"A battery energy storage systems engineer designs, integrates, commissions and operates BESS made of cells, BMS, PCS, EMS and fire safety systems. The role turns batteries into a flexible resource for peak shaving, renewable shifting and frequency response, and requires electrochemistry, power electronics, grid connection and strict safety discipline around thermal runaway."},responsibilities:{vi:["Định cỡ hệ BESS theo bài toán sử dụng: công suất, năng lượng, C-rate, tuổi thọ và suy giảm.","Kiểm tra thiết kế tích hợp cell, rack, BMS, PCS, biến áp và hệ thống phòng cháy, thông gió.","Lập và thực hiện quy trình nghiệm thu: thử dung lượng, hiệu suất khứ hồi, bảo vệ và đáp ứng lưới.","Giám sát vận hành qua EMS: SOC, SOH, nhiệt độ, lệch áp cell và cảnh báo an toàn.","Theo dõi bảo hành, phân tích suy giảm và đề xuất chiến lược vận hành kéo dài tuổi thọ."],en:["Size the BESS to the use case: power, energy, C-rate, lifetime and degradation.","Review the integration of cells, racks, BMS, PCS, transformer, fire protection and ventilation.","Write and run commissioning tests: capacity, round-trip efficiency, protection and grid response.","Monitor operation through the EMS: SOC, SOH, temperature, cell imbalance and safety alarms.","Track warranties, analyze degradation and propose operating strategies that extend life."]},competencies:[{name:{vi:"Điện hóa pin",en:"Battery electrochemistry"},desc:{vi:"Hiểu đặc tính LFP, NMC, LTO: điện áp, mật độ năng lượng, tuổi thọ chu kỳ và ngưỡng thoát nhiệt.",en:"Understand LFP, NMC and LTO: voltage, energy density, cycle life and thermal runaway thresholds."}},{name:{vi:"Điện tử công suất & lưới",en:"Power electronics & grid"},desc:{vi:"Cấu hình PCS, bảo vệ, chất lượng điện năng và yêu cầu đấu nối của đơn vị vận hành lưới.",en:"Configure the PCS, protection, power quality and grid operator connection requirements."}},{name:{vi:"Định cỡ & mô hình hóa",en:"Sizing & modeling"},desc:{vi:"Mô phỏng lịch nạp xả, suy giảm theo chu kỳ và theo lịch, tính năng lượng khả dụng thực.",en:"Simulate charge and discharge schedules, cycle and calendar fade, and real usable energy."}},{name:{vi:"An toàn hệ thống pin",en:"Battery safety"},desc:{vi:"Giữ nguyên liên động bảo vệ, phát hiện sớm bất thường nhiệt và phối hợp phương án chữa cháy.",en:"Keep protection interlocks intact, detect thermal anomalies early and coordinate fire response."}},{name:{vi:"Nghiệm thu & tài liệu",en:"Commissioning & documentation"},desc:{vi:"Lập quy trình thử, ghi nhận kết quả trung thực và quản lý hồ sơ cấu hình.",en:"Write test procedures, record results honestly and control configuration records."}}],knowledge:{vi:["IEC 62619 về yêu cầu an toàn cho cell và pin lithium thứ cấp dùng trong công nghiệp.","Bộ IEC 62933 về hệ thống lưu trữ năng lượng điện: thuật ngữ, thông số, thử nghiệm và an toàn.","UL 9540 về an toàn hệ lưu trữ năng lượng và UL 9540A về phương pháp thử lan truyền thoát nhiệt.","NFPA 855 về lắp đặt hệ thống lưu trữ năng lượng tĩnh: khoảng cách, phát hiện khí, chữa cháy.","Luật Điện lực số 61/2024/QH15 và yêu cầu đấu nối, vận hành của hệ thống điện."],en:["IEC 62619 safety requirements for secondary lithium cells and batteries for industrial use.","The IEC 62933 series on electrical energy storage systems: terms, parameters, testing and safety.","UL 9540 for energy storage system safety and UL 9540A test method for thermal runaway propagation.","NFPA 855 on stationary energy storage installation: spacing, gas detection and fire suppression.","Electricity Law No. 61/2024/QH15 and power system connection and operation requirements."]},tools:["Phần mềm EMS/SCADA","Giao diện BMS và nhật ký cell","Máy phân tích chất lượng điện","Camera nhiệt","Bộ thử dung lượng và tải giả","Phần mềm mô phỏng định cỡ BESS"],kpis:{vi:["Hệ số khả dụng của hệ BESS (%).","Hiệu suất khứ hồi thực tế so với thiết kế.","Tốc độ suy giảm SOH mỗi năm so với cam kết bảo hành.","Số cảnh báo nhiệt, quá áp chưa xử lý quá hạn (mục tiêu bằng 0)."],en:["BESS availability factor (%).","Actual versus design round-trip efficiency.","Annual SOH fade versus the warranty commitment.","Overdue thermal and overvoltage alarms (target zero)."]},day:[{time:"07:30",vi:"Đọc báo cáo đêm: SOC, nhiệt độ rack, lệch áp cell và các cảnh báo EMS.",en:"Read the overnight report: SOC, rack temperatures, cell imbalance and EMS alarms."},{time:"09:00",vi:"Kiểm tra hiện trường container: thông gió, cảm biến khí, hệ thống chữa cháy.",en:"Inspect the containers: ventilation, gas sensors and fire suppression."},{time:"11:00",vi:"Lập lịch nạp xả ngày mai theo dự báo bức xạ và khung giờ cao điểm.",en:"Plan tomorrow's charge and discharge schedule from irradiance forecasts and peak hours."},{time:"14:00",vi:"Chạy một bước thử nghiệm thu, đối chiếu kết quả với tiêu chí hợp đồng.",en:"Run a commissioning test step and compare results with contract criteria."},{time:"16:30",vi:"Cập nhật hồ sơ cấu hình BMS, nhật ký sự cố và báo cáo cho chủ đầu tư.",en:"Update the BMS configuration record, incident log and the owner's report."}],mistakes:{vi:["Cam kết năng lượng theo dung lượng danh định DC mà quên SOC, SOH và tổn hao chuyển đổi.","Nạp hồ sơ hóa học cell sai, khiến ngưỡng điện áp và nhiệt độ bảo vệ không phù hợp.","Tắt hoặc bỏ qua cảnh báo bảo vệ để chạy thử kịp tiến độ."],en:["Committing energy based on DC nameplate while ignoring SOC, SOH and conversion losses.","Loading the wrong cell chemistry profile so voltage and temperature limits no longer fit.","Muting or bypassing protection alarms to finish tests on schedule."]},career:[{vi:"Kỹ thuật viên vận hành BESS",en:"BESS operations technician"},{vi:"Kỹ sư hệ thống lưu trữ năng lượng",en:"Energy storage systems engineer"},{vi:"Kỹ sư trưởng tích hợp và nghiệm thu BESS",en:"Lead BESS integration and commissioning engineer"},{vi:"Giám đốc kỹ thuật dự án lưu trữ năng lượng",en:"Energy storage technical director"}],glossary:[{term:"SOC",vi:"Trạng thái nạp: phần trăm năng lượng còn lại so với dung lượng hiện có của pin.",en:"State of charge: the remaining energy as a percentage of current capacity."},{term:"SOH",vi:"Trạng thái sức khỏe: dung lượng hiện tại so với dung lượng danh định ban đầu.",en:"State of health: current capacity relative to the original nameplate capacity."},{term:"C-rate",vi:"Tỷ lệ công suất nạp xả so với dung lượng; 0.5C nghĩa là xả hết trong khoảng 2 giờ.",en:"Charge or discharge power relative to capacity; 0.5C means a full discharge in about 2 hours."},{term:"PCS",vi:"Hệ thống chuyển đổi công suất, nghịch lưu hai chiều giữa pin DC và lưới AC.",en:"Power conversion system, the bidirectional inverter between the DC battery and the AC grid."},{term:"Thermal runaway",vi:"Thoát nhiệt: phản ứng tỏa nhiệt tự gia tốc trong cell, có thể lan sang cell khác và gây cháy.",en:"A self-accelerating exothermic reaction in a cell that can spread to others and cause fire."}],quiz:[{q:{vi:"Hệ 1000 kWh DC, SOC 10-90%, SOH 90%, hiệu suất xả 95%. Năng lượng khả dụng tại POI là bao nhiêu?",en:"A 1000 kWh DC system, SOC 10-90%, SOH 90%, discharge efficiency 95%. What is the usable energy at the POI?"},options:{vi:["800 kWh","720 kWh","950 kWh","684 kWh"],en:["800 kWh","720 kWh","950 kWh","684 kWh"]},answer:3,explain:{vi:"Năng lượng khả dụng = 1000 x 0.8 x 0.9 x 0.95 = 684 kWh.",en:"Usable energy = 1000 x 0.8 x 0.9 x 0.95 = 684 kWh."}},{q:{vi:"Cell có điện áp danh định 3.2 V, ngưỡng nạp 3.65 V thường thuộc họ hóa học nào?",en:"A cell with 3.2 V nominal and a 3.65 V charge limit usually belongs to which chemistry?"},options:{vi:["NMC","LFP","LTO","Chì axit"],en:["NMC","LFP","LTO","Lead acid"]},answer:1,explain:{vi:"LFP có điện áp danh định khoảng 3.2 V; NMC khoảng 3.6-3.7 V và LTO khoảng 2.3-2.4 V.",en:"LFP is about 3.2 V nominal; NMC is about 3.6-3.7 V and LTO about 2.3-2.4 V."}},{q:{vi:"Hệ 2000 kWh xả ở công suất 1000 kW. C-rate xả là bao nhiêu?",en:"A 2000 kWh system discharges at 1000 kW. What is the discharge C-rate?"},options:{vi:["2C","1C","0.5C","0.25C"],en:["2C","1C","0.5C","0.25C"]},answer:2,explain:{vi:"C-rate = 1000 kW / 2000 kWh = 0.5C, tức xả hết trong khoảng 2 giờ.",en:"C-rate = 1000 kW / 2000 kWh = 0.5C, a full discharge in about 2 hours."}},{q:{vi:"Nhà thầu đề nghị tắt cảnh báo quá áp cell để chạy thử kịp tiến độ. Bạn làm gì?",en:"The contractor asks you to mute the cell overvoltage alarm to finish testing on time. What do you do?"},options:{vi:["Từ chối, dừng nạp, sửa cấu hình đúng và báo người có thẩm quyền","Tắt cảnh báo nhưng cử người theo dõi","Giảm công suất nạp rồi tắt cảnh báo","Chờ nhà cung cấp quyết định"],en:["Refuse, stop charging, fix the configuration and escalate","Mute it but assign someone to watch","Reduce charging power and mute it","Let the vendor decide"]},answer:0,explain:{vi:"Bảo vệ quá áp ngăn thoát nhiệt; không được vô hiệu hóa để chạy tiến độ.",en:"Overvoltage protection prevents thermal runaway; it must never be disabled for schedule reasons."}}]}},"KK-966":{scenario:{company:"Aquaville Urban Water",supervisor:{name:"Đỗ Văn Lâm",role:{vi:"Trưởng phòng Giảm thất thoát nước",en:"Non-revenue Water Manager"}},ref_code:"NRW-2610",title:{vi:"Tách đúng thất thoát. Giảm đúng chỗ rò.",en:"Split losses right. Fix real leaks."},brief:{vi:"Bạn lập cân bằng nước tháng 10 theo khung IWA cho vùng đồng hồ DMA-07, hồ sơ NRW-2610. Nước vào hệ thống 152400 m3; tiêu thụ hợp pháp có hóa đơn 118900 m3; hợp pháp không hóa đơn (chữa cháy, súc xả ống) 1600 m3; đồng hồ khách hàng đo thiếu ước tính 4300 m3; sử dụng trái phép 1200 m3. Sửa phân loại khoản đồng hồ đo thiếu và lượng thất thoát thực trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are building the October IWA water balance for district metered area DMA-07, file NRW-2610. System input volume 152400 m3; billed authorized consumption 118900 m3; unbilled authorized (firefighting, mains flushing) 1600 m3; estimated customer meter under-registration 4300 m3; unauthorized consumption 1200 m3. Correct the category of meter under-registration and the real losses in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Cân bằng nước IWA đã duyệt · NRW-2610",en:"Approved IWA water balance · NRW-2610"},fields:[{id:"METER_UR",label:{vi:"Phân loại khoản đồng hồ đo thiếu",en:"Meter under-registration category"},initial:"REAL-LOSS",expected:"APPARENT-LOSS",choices:["REAL-LOSS","APPARENT-LOSS","UNBILLED-AUTH"],reference:"Bảng cân bằng nước IWA",hint:{vi:"Nước đã đến tay khách hàng nhưng không được ghi nhận đủ là thất thoát thương mại, không phải rò rỉ vật lý.",en:"Water that reached the customer but was not fully recorded is a commercial loss, not a physical leak."}},{id:"REAL_LOSS",label:{vi:"Thất thoát thực tháng 10 (m3)",en:"October real losses (m3)"},initial:"30700",expected:"26400",reference:"Bảng tính thất thoát DMA-07",ref_value:{vi:"Vào 152400; có hóa đơn 118900; không hóa đơn 1600; đo thiếu 4300; trái phép 1200 (m3)",en:"Input 152400; billed 118900; unbilled 1600; meter error 4300; unauthorized 1200 (m3)"},hint:{vi:"Trừ đủ cả hai khoản thất thoát biểu kiến trước khi kết luận lượng rò rỉ vật lý.",en:"Deduct both apparent loss components before concluding the physical leakage volume."}}],sop32:{vi:"Thất thoát thực = nước vào hệ thống - tiêu thụ hợp pháp có hóa đơn - tiêu thụ hợp pháp không hóa đơn - thất thoát biểu kiến (đồng hồ đo thiếu + sử dụng trái phép), theo cân bằng nước IWA.",en:"Real losses = system input volume - billed authorized - unbilled authorized - apparent losses (meter under-registration + unauthorized use), per the IWA water balance."},context:{label:"SCADA / NRW-2610",metrics:[{label:{vi:"Nước vào DMA-07",en:"DMA-07 system input"},value:"152,400 m3"},{label:{vi:"Có hóa đơn",en:"Billed authorized"},value:"118,900 m3"},{label:{vi:"Lưu lượng đêm nhỏ nhất",en:"Minimum night flow"},value:"38 m3/h"}]},crisis:{vi:"Phó giám đốc nhắn: “Chuyển 8000 m3 sang mục súc xả ống cho tỷ lệ thất thoát quý này đạt chỉ tiêu, thưởng cả phòng phụ thuộc vào đó. Đoàn kiểm tra của tỉnh chỉ xem tổng thôi.”",en:"The deputy director messages you: “Move 8000 m3 into mains flushing so this quarter's loss rate meets the target, the whole team's bonus depends on it. The provincial inspectors only look at the totals.”"},options:{safe:{vi:"Giữ cân bằng nước đúng, từ chối ghi khống súc xả và báo giám đốc bằng văn bản; đề xuất dò rò chủ động, quản lý áp lực và thay đồng hồ cũ để giảm thất thoát thật.",en:"Keep the true water balance, refuse to inflate flushing volumes and inform the director in writing; propose active leak detection, pressure management and old meter replacement."},shortcut:{vi:"Ghi thêm 8000 m3 súc xả ống để đạt chỉ tiêu quý, quý sau điều chỉnh lại cho khớp.",en:"Record an extra 8000 m3 of flushing to meet the quarterly target and reconcile next quarter."},wait:{vi:"Không nộp báo cáo, chờ ban giám đốc tự quyết định số liệu.",en:"Hold the report and wait for management to decide the figures."}},questions:{vi:["Vì sao đồng hồ đo thiếu là thất thoát biểu kiến? Phân loại sai ảnh hưởng thế nào tới kế hoạch dò rò?","Trình bày cách tính thất thoát thực 26400 m3 và rủi ro pháp lý, uy tín nếu ghi khống tiêu thụ không hóa đơn."],en:["Why is meter under-registration an apparent loss? How does misclassifying it affect the leak detection plan?","Explain how you derived real losses and the legal and reputational risk of inflating unbilled consumption."]},hints:{vi:["Xem kết quả kiểm định đồng hồ và nhật ký kiểm tra trước khi xếp từng khoản vào cân bằng nước.","Trừ lần lượt từng thành phần theo SOP mục 3.2, đừng bỏ sót khoản nào của thất thoát biểu kiến.","Đọc lại SOP mục 4.2: số liệu cân bằng nước không được điều chỉnh vì chỉ tiêu; báo cáo áp lực bằng văn bản."],en:["Check the meter test and inspection log before placing each item in the water balance.","Subtract each component in turn per SOP 3.2 and do not miss any apparent loss item.","Re-read SOP 4.2: water balance figures must never be adjusted to meet targets; report pressure in writing."]},terminal:{system:"scada-dma",settable:["METER_UR","REAL_LOSS"],commands:[{cmd:"flow dma-07",out:{vi:"Nước vào DMA-07 tháng 10/2026: 152400 m3. Lưu lượng đêm nhỏ nhất 38 m3/h lúc 02:30, tăng 6 m3/h so với tháng 9.",en:"DMA-07 input in October 2026: 152400 m3. Minimum night flow 38 m3/h at 02:30, up 6 m3/h from September."}},{cmd:"billing summary",out:{vi:"Tiêu thụ có hóa đơn: 118900 m3. Hợp pháp không hóa đơn (chữa cháy, súc xả ống): 1600 m3.",en:"Billed authorized: 118900 m3. Unbilled authorized (firefighting, mains flushing): 1600 m3."}},{cmd:"meter test",out:{vi:"Kiểm định mẫu 200 đồng hồ khách hàng trên 10 năm tuổi: phần lớn chạy chậm ở lưu lượng thấp, ước tính đo thiếu 4300 m3.",en:"Sample test of 200 customer meters older than 10 years: most under-read at low flow, estimated under-registration 4300 m3."}},{cmd:"cat inspection.log",out:{vi:"Phát hiện 14 đấu nối trái phép tại tổ 5 và tổ 9, ước tính sử dụng 1200 m3.",en:"Found 14 illegal connections in blocks 5 and 9, estimated use 1200 m3."}},{cmd:"pressure log",out:{vi:"Áp lực ban đêm tại điểm áp lực trung bình vùng 3.8 bar, cao hơn mức mục tiêu 2.5 bar.",en:"Night pressure at the average zone point is 3.8 bar, above the 2.5 bar target."}}]}},learning:{summary:{vi:"Kỹ sư cấp thoát nước đô thị thiết kế, vận hành và tối ưu mạng lưới cấp nước, thoát nước mưa và nước thải: tính thủy lực, phân vùng tách mạng (DMA), giảm thất thoát, bảo đảm chất lượng nước và chống ngập. Nghề đòi hỏi vững thủy lực, dữ liệu SCADA, GIS và tính trung thực trong số liệu phục vụ cộng đồng.",en:"An urban water supply and drainage engineer designs, operates and optimizes water distribution, stormwater and sewer networks: hydraulic analysis, district metered areas (DMA), loss reduction, water quality and flood control. The role requires solid hydraulics, SCADA data, GIS skills and honest data that serves the public."},responsibilities:{vi:["Lập mô hình thủy lực, kiểm tra áp lực, lưu lượng và kích thước đường ống cấp, thoát nước.","Thiết lập và theo dõi vùng DMA, phân tích lưu lượng đêm nhỏ nhất để khoanh vùng rò rỉ.","Lập cân bằng nước IWA, tính NRW, thất thoát thực, thất thoát biểu kiến và chỉ số ILI.","Giám sát chất lượng nước tại điểm cuối mạng và phối hợp xử lý sự cố vỡ ống, ngập úng.","Lập kế hoạch cải tạo, thay ống và đồng hồ, quản lý áp lực và báo cáo cơ quan quản lý."],en:["Build hydraulic models and check pressure, flow and pipe sizes for supply and drainage networks.","Set up and monitor DMAs and analyze minimum night flow to locate leaks.","Prepare the IWA water balance: NRW, real losses, apparent losses and the ILI.","Monitor water quality at network extremities and coordinate response to bursts and flooding.","Plan pipe and meter renewal, pressure management and reporting to regulators."]},competencies:[{name:{vi:"Thủy lực mạng lưới",en:"Network hydraulics"},desc:{vi:"Tính tổn thất áp lực, mô phỏng mạng và chọn đường kính, bơm, van phù hợp.",en:"Compute head losses, simulate networks and select suitable pipes, pumps and valves."}},{name:{vi:"Quản lý thất thoát",en:"Water loss management"},desc:{vi:"Áp dụng cân bằng nước IWA, phân tích MNF, dò rò chủ động và quản lý áp lực.",en:"Apply the IWA water balance, MNF analysis, active leak detection and pressure management."}},{name:{vi:"Dữ liệu SCADA & GIS",en:"SCADA & GIS data"},desc:{vi:"Khai thác dữ liệu đồng hồ tổng, logger áp lực và bản đồ mạng để ra quyết định.",en:"Use bulk meters, pressure loggers and network maps to drive decisions."}},{name:{vi:"Chất lượng nước & môi trường",en:"Water quality & environment"},desc:{vi:"Theo dõi clo dư, độ đục và tuân thủ quy chuẩn nước sạch, nước thải.",en:"Track residual chlorine, turbidity and compliance with drinking water and effluent standards."}},{name:{vi:"Trung thực & phục vụ cộng đồng",en:"Integrity & public service"},desc:{vi:"Báo cáo đúng số liệu thất thoát, không làm đẹp chỉ tiêu, ưu tiên an toàn người dùng nước.",en:"Report losses truthfully, never dress up targets and put water users' safety first."}}],knowledge:{vi:["Khung cân bằng nước IWA: tiêu thụ hợp pháp, thất thoát biểu kiến, thất thoát thực và nước không doanh thu (NRW).","Chỉ số ILI = thất thoát thực hằng năm hiện tại / thất thoát thực tối thiểu không tránh được (UARL).","QCVN 01-1:2018/BYT về chất lượng nước sạch sử dụng cho mục đích sinh hoạt.","Nghị định 117/2007/NĐ-CP về sản xuất, cung cấp và tiêu thụ nước sạch; Nghị định 80/2014/NĐ-CP về thoát nước và xử lý nước thải.","TCVN 13606:2023 về thiết kế mạng lưới đường ống và công trình cấp nước; TCVN 7957 về mạng lưới thoát nước bên ngoài."],en:["The IWA water balance: authorized consumption, apparent losses, real losses and non-revenue water (NRW).","ILI = current annual real losses / unavoidable annual real losses (UARL).","QCVN 01-1:2018/BYT on domestic drinking water quality.","Decree 117/2007/ND-CP on clean water production, supply and consumption; Decree 80/2014/ND-CP on drainage and wastewater treatment.","TCVN 13606:2023 on water supply network and facility design; TCVN 7957 on external drainage networks."]},tools:["SCADA và đồng hồ tổng DMA","Phần mềm mô hình thủy lực (EPANET)","Thiết bị dò rò âm học và tương quan","GIS mạng lưới (QGIS)","Logger áp lực và lưu lượng","Phần mềm mô phỏng thoát nước (SWMM)"],kpis:{vi:["Tỷ lệ nước không doanh thu NRW (%).","Thất thoát thực tính theo lít/đấu nối/ngày hoặc chỉ số ILI.","Thời gian trung bình khắc phục sự cố vỡ ống.","Tỷ lệ mẫu nước đạt quy chuẩn tại điểm cuối mạng."],en:["Non-revenue water rate NRW (%).","Real losses in liters per connection per day or ILI.","Average time to repair pipe bursts.","Share of water samples compliant at network extremities."]},day:[{time:"07:30",vi:"Xem lưu lượng đêm nhỏ nhất của các DMA, đánh dấu vùng tăng bất thường.",en:"Review minimum night flows across DMAs and flag abnormal increases."},{time:"09:00",vi:"Cử tổ dò rò theo vùng nghi vấn, kiểm tra kết quả tương quan âm học.",en:"Dispatch leak crews to suspect zones and review correlator results."},{time:"11:00",vi:"Hiệu chỉnh mô hình thủy lực với số liệu logger áp lực mới.",en:"Calibrate the hydraulic model with new pressure logger data."},{time:"14:00",vi:"Lập cân bằng nước tháng, đối chiếu số liệu hóa đơn và kiểm định đồng hồ.",en:"Prepare the monthly water balance, reconciling billing and meter test data."},{time:"16:30",vi:"Họp kế hoạch thay ống, van giảm áp và báo cáo lãnh đạo.",en:"Plan pipe and pressure valve renewal and report to management."}],mistakes:{vi:["Xếp đồng hồ đo thiếu vào thất thoát thực, dẫn tới dò rò sai chỗ và lãng phí nguồn lực.","Chỉ báo cáo tỷ lệ NRW theo phần trăm, bỏ qua chỉ số theo đấu nối hoặc ILI.","Duy trì áp lực đêm quá cao, làm tăng rò rỉ và tần suất vỡ ống."],en:["Classing meter under-registration as real loss, sending crews to the wrong place and wasting resources.","Reporting NRW only as a percentage and ignoring per-connection indicators or ILI.","Keeping night pressure too high, which raises leakage and burst frequency."]},career:[{vi:"Kỹ thuật viên vận hành mạng cấp nước",en:"Water network technician"},{vi:"Kỹ sư cấp thoát nước",en:"Water supply and drainage engineer"},{vi:"Trưởng nhóm giảm thất thoát / quy hoạch mạng lưới",en:"NRW or network planning lead"},{vi:"Giám đốc kỹ thuật công ty cấp thoát nước",en:"Technical director of a water utility"}],glossary:[{term:"NRW",vi:"Nước không doanh thu: lượng nước vào hệ thống trừ tiêu thụ hợp pháp có hóa đơn.",en:"Non-revenue water: system input volume minus billed authorized consumption."},{term:"DMA",vi:"Vùng đồng hồ tổng: khu vực mạng được cô lập, đo lưu lượng vào ra để theo dõi thất thoát.",en:"District metered area: an isolated network zone with metered inflows to track losses."},{term:"MNF",vi:"Lưu lượng đêm nhỏ nhất, thường lúc 2-4 giờ sáng, phản ánh rõ nhất lượng rò rỉ.",en:"Minimum night flow, usually at 2-4 am, the clearest indicator of leakage."},{term:"Apparent loss",vi:"Thất thoát biểu kiến: nước đã dùng nhưng không được ghi nhận đúng do đồng hồ sai hoặc dùng trái phép.",en:"Water used but not correctly recorded due to meter error or unauthorized use."},{term:"ILI",vi:"Chỉ số rò rỉ hạ tầng: tỷ số giữa thất thoát thực hiện tại và mức tối thiểu không tránh được.",en:"Infrastructure leakage index: current real losses divided by the unavoidable minimum."}],quiz:[{q:{vi:"Đồng hồ khách hàng chạy chậm ở lưu lượng thấp thuộc thành phần nào trong cân bằng nước IWA?",en:"Customer meters under-reading at low flow belong to which IWA water balance component?"},options:{vi:["Thất thoát thực","Thất thoát biểu kiến","Tiêu thụ hợp pháp không hóa đơn","Tiêu thụ có hóa đơn"],en:["Real losses","Apparent losses","Unbilled authorized consumption","Billed consumption"]},answer:1,explain:{vi:"Sai số đồng hồ và sử dụng trái phép là thất thoát biểu kiến, không phải rò rỉ vật lý.",en:"Meter inaccuracy and unauthorized use are apparent losses, not physical leakage."}},{q:{vi:"Nước vào 100000 m3, có hóa đơn 78000 m3, hợp pháp không hóa đơn 1000 m3. NRW là bao nhiêu?",en:"Input 100000 m3, billed authorized 78000 m3, unbilled authorized 1000 m3. What is NRW?"},options:{vi:["21000 m3","79000 m3","22000 m3","23000 m3"],en:["21000 m3","79000 m3","22000 m3","23000 m3"]},answer:2,explain:{vi:"NRW = nước vào - tiêu thụ có hóa đơn = 100000 - 78000 = 22000 m3; NRW gồm cả tiêu thụ không hóa đơn.",en:"NRW = input - billed authorized = 100000 - 78000 = 22000 m3; it includes unbilled authorized use."}},{q:{vi:"Lãnh đạo yêu cầu ghi khống lượng súc xả ống để đạt chỉ tiêu thất thoát. Bạn làm gì?",en:"Management asks you to inflate mains flushing volumes to meet the loss target. What do you do?"},options:{vi:["Từ chối, giữ số liệu đúng, báo cáo bằng văn bản và đề xuất giải pháp giảm rò thật","Làm theo vì chỉ ảnh hưởng nội bộ","Ghi một nửa cho an toàn","Nghỉ phép để tránh"],en:["Refuse, keep true data, report in writing and propose real leak reduction","Comply since it is internal only","Record half to be safe","Take leave to avoid it"]},answer:0,explain:{vi:"Số liệu cân bằng nước là cơ sở quản lý và báo cáo nhà nước; làm sai là vi phạm và che giấu rò rỉ thật.",en:"Water balance data underpins management and official reporting; falsifying it is a violation and hides real leaks."}},{q:{vi:"Vì sao lưu lượng đêm nhỏ nhất (MNF) quan trọng trong dò rò?",en:"Why is minimum night flow (MNF) important for leak detection?"},options:{vi:["Vì giá nước ban đêm thấp","Vì áp lực ban đêm thấp nhất","Vì đồng hồ chính xác hơn ban đêm","Vì tiêu thụ hợp pháp thấp nhất nên rò rỉ chiếm tỷ trọng lớn nhất"],en:["Night tariffs are lower","Night pressure is lowest","Meters are more accurate at night","Legitimate use is lowest so leakage dominates the flow"]},answer:3,explain:{vi:"Ban đêm tiêu thụ hợp pháp thấp nhất nên phần lớn lưu lượng là rò rỉ; áp lực đêm thực tế lại cao.",en:"At night legitimate use is lowest so most flow is leakage, while night pressure is actually high."}}]}},"KK-967":{scenario:{company:"Solvenna Power Trading",supervisor:{name:"Mạc Thị Hồng Nhung",role:{vi:"Trưởng bộ phận Giao dịch & Quyết toán điện",en:"Head of Power Trading & Settlement"}},ref_code:"ST-1026",title:{vi:"Đúng giá tham chiếu. Đúng tiền quyết toán.",en:"Right reference price. Right settlement."},brief:{vi:"Bạn lập bảng quyết toán hợp đồng sai khác (CfD) tháng 10, hồ sơ ST-1026, giữa nhà máy điện gió của công ty và một khách hàng mua điện trực tiếp (DPPA) qua lưới quốc gia. Giá hợp đồng 1850 đ/kWh; sản lượng hợp đồng tính thanh toán 3000000 kWh; SMP bình quân gia quyền 1286 đ/kWh, CAN 197 đ/kWh. Hợp đồng quy định giá tham chiếu là giá thị trường toàn phần. Sửa giá tham chiếu và tiền quyết toán (triệu đồng) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are preparing the October contract for difference (CfD) settlement, file ST-1026, between the company's wind farm and a direct power purchase (DPPA) customer via the national grid. Strike price 1850 VND/kWh; contracted settlement volume 3000000 kWh; volume-weighted SMP 1286 VND/kWh, CAN 197 VND/kWh. The contract sets the full market price as the reference. Correct the reference price and the settlement amount (million VND) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Hợp đồng CfD & dữ liệu giá đã xác nhận · ST-1026",en:"CfD contract & confirmed price data · ST-1026"},fields:[{id:"REF_PRICE",label:{vi:"Giá tham chiếu CfD",en:"CfD reference price"},initial:"SMP",expected:"FMP",choices:["SMP","FMP","CAN"],reference:"Điều khoản quyết toán hợp đồng",hint:{vi:"Giá thị trường toàn phần gồm cả giá điện năng thị trường và giá công suất thị trường của từng chu kỳ.",en:"The full market price combines the market energy price and the market capacity price of each period."}},{id:"CFD_MVND",label:{vi:"Tiền quyết toán CfD (triệu đồng)",en:"CfD settlement (million VND)"},initial:"1692",expected:"1101",reference:"Bảng quyết toán tháng 10",ref_value:{vi:"Giá hợp đồng 1850; SMP 1286; CAN 197 (đ/kWh); sản lượng 3000000 kWh",en:"Strike 1850; SMP 1286; CAN 197 (VND/kWh); volume 3000000 kWh"},hint:{vi:"Lấy giá hợp đồng trừ giá tham chiếu đúng điều khoản, nhân với sản lượng hợp đồng rồi đổi sang triệu đồng.",en:"Subtract the contractual reference price from the strike, multiply by contracted volume and convert to million VND."}}],sop32:{vi:"Tiền quyết toán CfD = (giá hợp đồng - giá tham chiếu) x sản lượng hợp đồng; giá tham chiếu FMP = SMP + CAN bình quân gia quyền theo sản lượng; kết quả dương thì bên mua trả cho bên bán.",en:"CfD settlement = (strike price - reference price) x contracted volume; reference FMP = SMP + CAN, volume-weighted; a positive result means the buyer pays the seller."},context:{label:"ETRM / ST-1026",metrics:[{label:{vi:"Giá hợp đồng",en:"Strike price"},value:"1,850 VND/kWh"},{label:{vi:"SMP bình quân gia quyền",en:"Volume-weighted SMP"},value:"1,286 VND/kWh"},{label:{vi:"Giá công suất CAN",en:"Capacity price CAN"},value:"197 VND/kWh"},{label:{vi:"Sản lượng hợp đồng",en:"Contracted volume"},value:"3,000,000 kWh"}]},crisis:{vi:"Giám đốc thương mại nhắn: “Cứ xuất hóa đơn theo SMP như bản nháp, khách hàng chưa chắc đã đối chiếu, khoản chênh gần 600 triệu là lợi nhuận quý này. Nếu họ hỏi thì bảo lỗi hệ thống.”",en:"The commercial director messages you: “Invoice on SMP as in the draft, the customer may never reconcile it and the gap of almost 600 million is this quarter's profit. If they ask, call it a system error.”"},options:{safe:{vi:"Quyết toán theo FMP đúng hợp đồng, báo giám đốc tài chính và pháp chế bằng văn bản; rà soát các kỳ trước và thông báo minh bạch cho khách hàng nếu đã tính sai.",en:"Settle on FMP per the contract, inform the CFO and legal in writing; review earlier periods and notify the customer transparently if they were miscalculated."},shortcut:{vi:"Xuất hóa đơn theo SMP, chỉ điều chỉnh khi khách hàng phát hiện và khiếu nại.",en:"Invoice on SMP and only adjust if the customer notices and complains."},wait:{vi:"Treo bảng quyết toán, chờ giám đốc thương mại và khách hàng tự thương lượng.",en:"Hold the settlement and wait for the commercial director and the customer to negotiate."}},questions:{vi:["Vì sao giá tham chiếu phải là FMP chứ không phải SMP? Dữ liệu nào cho ra số tiền quyết toán đã sửa?","Nếu các tháng trước đã quyết toán theo SMP, bạn xử lý rủi ro hợp đồng và quan hệ khách hàng như thế nào?"],en:["Why must the reference be FMP rather than SMP? Which data produces the corrected settlement amount?","If earlier months were settled on SMP, how do you handle the contractual risk and the customer relationship?"]},hints:{vi:["Đọc kỹ điều khoản định nghĩa giá tham chiếu trong hợp đồng trước khi chọn chuỗi giá.","Cộng đủ các thành phần của giá tham chiếu rồi mới lấy chênh lệch theo SOP mục 3.2.","Đọc lại SOP mục 4.2: quyết toán phải đúng hợp đồng; mọi chỉ đạo xuất hóa đơn sai phải được báo cáo."],en:["Read the contract clause defining the reference price before choosing the price series.","Add every component of the reference price before taking the difference in SOP 3.2.","Re-read SOP 4.2: settlement must follow the contract; any instruction to misbill must be escalated."]}},learning:{summary:{vi:"Chuyên viên phân tích thị trường điện theo dõi giá thị trường bán buôn, dự báo phụ tải và giá, xây dựng chiến lược chào giá, quản lý danh mục hợp đồng (PPA, DPPA, CfD) và quyết toán. Nghề tạo ra quyết định mua bán điện có căn cứ, kiểm soát rủi ro giá và sản lượng, đòi hỏi kỹ năng định lượng, hiểu quy định thị trường và liêm chính tuyệt đối.",en:"An electricity market analyst tracks wholesale prices, forecasts load and prices, builds bidding strategies, manages contract portfolios (PPA, DPPA, CfD) and settlement. The role produces well-founded trading decisions and controls price and volume risk, requiring quantitative skills, knowledge of market rules and absolute integrity."},responsibilities:{vi:["Dự báo phụ tải, thủy văn, giá nhiên liệu và giá thị trường theo chu kỳ giao dịch.","Xây dựng chiến lược chào giá và lịch huy động tối ưu cho danh mục nhà máy.","Định giá, đàm phán và theo dõi hợp đồng PPA, DPPA, CfD và hợp đồng phòng ngừa rủi ro.","Lập và đối chiếu bảng quyết toán với dữ liệu giá, sản lượng đã xác nhận.","Báo cáo vị thế rủi ro, lãi lỗ và tuân thủ quy tắc liêm chính thị trường."],en:["Forecast load, hydrology, fuel prices and market prices for each trading period.","Build bidding strategies and optimal dispatch schedules for the plant portfolio.","Price, negotiate and monitor PPA, DPPA, CfD and hedging contracts.","Prepare and reconcile settlement statements against confirmed price and volume data.","Report risk positions, profit and loss and compliance with market integrity rules."]},competencies:[{name:{vi:"Phân tích định lượng",en:"Quantitative analysis"},desc:{vi:"Dùng thống kê, chuỗi thời gian và mô hình kịch bản để dự báo giá và sản lượng.",en:"Use statistics, time series and scenario models to forecast prices and volumes."}},{name:{vi:"Hiểu luật chơi thị trường",en:"Market rules"},desc:{vi:"Nắm cơ chế hình thành SMP, CAN, FMP, quy trình chào giá và quyết toán.",en:"Understand how SMP, CAN and FMP are formed, bidding procedures and settlement."}},{name:{vi:"Quản trị rủi ro",en:"Risk management"},desc:{vi:"Đo và phòng ngừa rủi ro giá, rủi ro sản lượng, rủi ro hình dạng phụ tải và đối tác.",en:"Measure and hedge price, volume, shape and counterparty risk."}},{name:{vi:"Pháp lý hợp đồng",en:"Contract literacy"},desc:{vi:"Đọc chính xác điều khoản giá tham chiếu, sản lượng, phạt và giải quyết tranh chấp.",en:"Read reference price, volume, penalty and dispute clauses precisely."}},{name:{vi:"Liêm chính thị trường",en:"Market integrity"},desc:{vi:"Từ chối thông đồng, thao túng giá chào và quyết toán sai; báo cáo bộ phận tuân thủ.",en:"Refuse collusion, bid manipulation and misbilling; escalate to compliance."}}],knowledge:{vi:["Luật Điện lực số 61/2024/QH15 và các quy định hướng dẫn về thị trường điện cạnh tranh.","Thị trường bán buôn điện cạnh tranh Việt Nam: chu kỳ giao dịch, SMP, CAN và FMP = SMP + CAN.","Cơ chế mua bán điện trực tiếp (DPPA) qua lưới quốc gia và hợp đồng sai khác theo quy định hiện hành.","Điều độ kinh tế theo thứ tự chi phí biên (merit order) và ảnh hưởng của thủy văn, nhiên liệu.","Quy tắc liêm chính thị trường: cấm thông đồng, thao túng giá chào và lạm dụng thông tin nội bộ."],en:["Electricity Law No. 61/2024/QH15 and guidance on the competitive electricity market.","Vietnam's competitive wholesale market: trading periods, SMP, CAN and FMP = SMP + CAN.","Direct power purchase (DPPA) via the national grid and contracts for difference under current rules.","Economic dispatch by marginal cost (merit order) and the impact of hydrology and fuel.","Market integrity rules: no collusion, bid manipulation or misuse of inside information."]},tools:["Hệ thống quản lý giao dịch năng lượng (ETRM)","Dữ liệu giá thị trường theo chu kỳ","Python hoặc R cho dự báo","Mô hình điều độ kinh tế","Bảng tính quyết toán","Công cụ trực quan hóa dữ liệu (BI)"],kpis:{vi:["Sai số dự báo giá và phụ tải (MAPE) theo tuần.","Tỷ lệ bảng quyết toán đúng ngay lần đầu, không phải điều chỉnh.","Lãi lỗ danh mục so với ngân sách trong giới hạn rủi ro được duyệt.","Số vi phạm quy tắc thị trường và tuân thủ (mục tiêu bằng 0)."],en:["Weekly price and load forecast error (MAPE).","Right-first-time settlement statements with no adjustments.","Portfolio profit and loss versus budget within approved risk limits.","Market rule and compliance breaches (target zero)."]},day:[{time:"07:30",vi:"Đọc kết quả thị trường ngày hôm trước, giá SMP, CAN và các sự kiện nghẽn mạch.",en:"Review yesterday's market results, SMP, CAN and congestion events."},{time:"09:00",vi:"Cập nhật dự báo phụ tải, thủy văn và giá nhiên liệu cho ngày tới.",en:"Update load, hydrology and fuel price forecasts for the day ahead."},{time:"11:00",vi:"Đề xuất bản chào giá và trình trưởng bộ phận phê duyệt trước giờ đóng cửa.",en:"Propose the bid and get approval from the head of trading before gate closure."},{time:"14:00",vi:"Đối chiếu sản lượng, giá và lập bảng quyết toán hợp đồng với khách hàng.",en:"Reconcile volumes and prices and prepare customer contract settlements."},{time:"16:30",vi:"Báo cáo vị thế rủi ro, lãi lỗ và các điểm cần chú ý cho ngày mai.",en:"Report risk positions, profit and loss and watch points for tomorrow."}],mistakes:{vi:["Dùng SMP thay cho FMP khi hợp đồng quy định giá tham chiếu là giá thị trường toàn phần.","Lấy giá bình quân số học thay vì bình quân gia quyền theo sản lượng khi quyết toán.","Nhầm chiều thanh toán của CfD, dẫn tới xuất hóa đơn ngược bên."],en:["Using SMP instead of FMP when the contract defines the full market price as reference.","Using a simple average instead of a volume-weighted average in settlement.","Getting the CfD payment direction wrong and invoicing the wrong party."]},career:[{vi:"Chuyên viên dữ liệu thị trường điện",en:"Power market data analyst"},{vi:"Chuyên viên phân tích thị trường và giao dịch điện",en:"Electricity market and trading analyst"},{vi:"Trưởng nhóm giao dịch và quản trị rủi ro",en:"Trading and risk management lead"},{vi:"Giám đốc thương mại năng lượng",en:"Head of energy commercial"}],glossary:[{term:"SMP",vi:"Giá điện năng thị trường của từng chu kỳ giao dịch, xác định theo giá chào biên.",en:"System marginal price for each trading period, set by the marginal bid."},{term:"CAN",vi:"Giá công suất thị trường, bù chi phí cố định cho nhà máy mới tốt nhất.",en:"Market capacity price that covers fixed costs of the best new entrant plant."},{term:"FMP",vi:"Giá thị trường toàn phần, bằng tổng SMP và CAN của chu kỳ giao dịch.",en:"Full market price, the sum of SMP and CAN for a trading period."},{term:"CfD",vi:"Hợp đồng sai khác: hai bên thanh toán phần chênh giữa giá hợp đồng và giá tham chiếu.",en:"Contract for difference: parties settle the gap between the strike and reference prices."},{term:"DPPA",vi:"Cơ chế mua bán điện trực tiếp giữa đơn vị phát điện tái tạo và khách hàng sử dụng điện lớn.",en:"Direct power purchase between a renewable generator and a large electricity user."}],quiz:[{q:{vi:"SMP của chu kỳ là 1200 đ/kWh, CAN là 250 đ/kWh. FMP bằng bao nhiêu?",en:"A period has SMP 1200 VND/kWh and CAN 250 VND/kWh. What is the FMP?"},options:{vi:["950 đ/kWh","1200 đ/kWh","1450 đ/kWh","1725 đ/kWh"],en:["950 VND/kWh","1200 VND/kWh","1450 VND/kWh","1725 VND/kWh"]},answer:2,explain:{vi:"FMP = SMP + CAN = 1200 + 250 = 1450 đ/kWh.",en:"FMP = SMP + CAN = 1200 + 250 = 1450 VND/kWh."}},{q:{vi:"CfD giá hợp đồng 1700 đ/kWh, FMP 1500 đ/kWh, sản lượng 2000000 kWh. Kết quả quyết toán là gì?",en:"CfD strike 1700 VND/kWh, FMP 1500 VND/kWh, volume 2000000 kWh. What is the settlement?"},options:{vi:["Bên mua trả bên bán 400 triệu đồng","Bên bán trả bên mua 400 triệu đồng","Bên mua trả bên bán 3400 triệu đồng","Không phát sinh thanh toán"],en:["Buyer pays seller 400 million VND","Seller pays buyer 400 million VND","Buyer pays seller 3400 million VND","No payment"]},answer:0,explain:{vi:"(1700 - 1500) x 2000000 = 400 triệu đồng; giá hợp đồng cao hơn giá tham chiếu nên bên mua trả bên bán.",en:"(1700 - 1500) x 2000000 = 400 million VND; the strike is above the reference, so the buyer pays the seller."}},{q:{vi:"Một nhà máy khác gợi ý hai bên “phối hợp” giá chào ngày mai. Bạn làm gì?",en:"Another plant suggests both sides “coordinate” tomorrow's bids. What do you do?"},options:{vi:["Đồng ý nếu chỉ một lần","Trao đổi qua điện thoại cá nhân","Chỉ chia sẻ giá chào cũ","Từ chối, lưu bằng chứng và báo bộ phận tuân thủ"],en:["Agree if it is only once","Discuss it on a personal phone","Share only past bids","Refuse, keep evidence and report to compliance"]},answer:3,explain:{vi:"Thông đồng giá chào là hành vi thao túng thị trường bị cấm; phải từ chối và báo cáo.",en:"Bid coordination is prohibited market manipulation; refuse and report it."}},{q:{vi:"Rủi ro hình dạng (shape risk) trong hợp đồng điện là gì?",en:"What is shape risk in a power contract?"},options:{vi:["Rủi ro đối tác mất khả năng thanh toán","Rủi ro biểu đồ sản lượng thực tế lệch với biểu đồ giá theo giờ","Rủi ro thay đổi tỷ giá","Rủi ro hư hỏng thiết bị"],en:["Counterparty default risk","Risk that the actual output profile mismatches the hourly price profile","Exchange rate risk","Equipment failure risk"]},answer:1,explain:{vi:"Sản lượng tái tạo thường cao vào giờ giá thấp, làm giá thu được bình quân thấp hơn giá thị trường bình quân.",en:"Renewable output is often high when prices are low, so the captured price falls below the average market price."}}]}},"KK-968":{scenario:{company:"Coralis Offshore Operating",supervisor:{name:"Châu Minh Tường",role:{vi:"Giám sát Vận hành Khai thác",en:"Production Superintendent"}},ref_code:"DPR-2810",title:{vi:"Phân loại đúng hao hụt. Tính đúng dầu thực.",en:"Classify deferment right. Count net oil."},brief:{vi:"Bạn hoàn thiện báo cáo hao hụt sản lượng ngày 28/10, hồ sơ DPR-2810, của một giàn khai thác. Máy nén khí gaslift K-201 trip bất ngờ do rung cao, giếng W-12 dừng từ 03:12 đến 12:12 (9 giờ). Phép thử giếng hợp lệ gần nhất ngày 25/10: chất lỏng 2300 bbl/ngày, độ ngậm nước 20%. Sửa loại hao hụt và lượng dầu hao hụt trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are completing the 28/10 production deferment report, file DPR-2810, for an offshore platform. Gas lift compressor K-201 tripped unexpectedly on high vibration and well W-12 was shut in from 03:12 to 12:12 (9 hours). The latest valid well test on 25/10: liquid 2300 bbl/d, water cut 20%. Correct the deferment category and the deferred oil volume in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Ma trận hao hụt & phép thử giếng đã duyệt · DPR-2810",en:"Approved deferment matrix & well tests · DPR-2810"},fields:[{id:"DEFER_CAT",label:{vi:"Phân loại hao hụt sản lượng",en:"Deferment category"},initial:"DEF-PLAN",expected:"DEF-UNPLAN",choices:["DEF-PLAN","DEF-UNPLAN","DEF-EXTERNAL"],reference:"Ma trận phân loại hao hụt",hint:{vi:"Sự cố thiết bị không nằm trong kế hoạch bảo dưỡng đã duyệt là hao hụt ngoài kế hoạch, dù thời gian dừng ngắn.",en:"An equipment failure outside the approved maintenance plan is unplanned deferment, however short the outage."}},{id:"DEFER_BBL",label:{vi:"Lượng dầu hao hụt (bbl)",en:"Deferred oil (bbl)"},initial:"862.5",expected:"690",reference:"Bảng tính hao hụt sản lượng",ref_value:{vi:"Phép thử hợp lệ 25/10: chất lỏng 2300 bbl/ngày, ngậm nước 20%; dừng 9 giờ",en:"Valid test 25/10: liquid 2300 bbl/d, water cut 20%; downtime 9 h"},hint:{vi:"Hao hụt tính trên dầu thực đã trừ nước, theo phép thử hợp lệ gần nhất và thời gian dừng quy về ngày.",en:"Deferment is counted on net oil after water, using the latest valid test and downtime converted to days."}}],sop32:{vi:"Dầu hao hụt (bbl) = lưu lượng chất lỏng của phép thử hợp lệ gần nhất x (1 - độ ngậm nước) x số giờ dừng / 24; không dùng phép thử đã bị thay thế.",en:"Deferred oil (bbl) = liquid rate of the latest valid well test x (1 - water cut) x hours down / 24; never use a superseded test."},context:{label:"DCS / DPR-2810",metrics:[{label:{vi:"Thời gian dừng W-12",en:"W-12 downtime"},value:"9 h"},{label:{vi:"Chất lỏng (phép thử 25/10)",en:"Liquid (25/10 test)"},value:"2,300 bbl/d"},{label:{vi:"Độ ngậm nước",en:"Water cut"},value:"20%"}]},crisis:{vi:"Trưởng ca nhắn: “Bypass liên động rung cao của K-201 rồi chạy lại ngay, tôi cử người đứng canh. Mất thêm vài giờ là trượt chỉ tiêu tháng, cứ ghi hao hụt theo kế hoạch cho đẹp báo cáo.”",en:"The shift supervisor messages you: “Bypass the K-201 high vibration trip and restart now, I will post someone to watch it. A few more hours and we miss the monthly target, just book it as planned deferment.”"},options:{safe:{vi:"Không bypass khi chưa có phiếu phê duyệt và đánh giá rủi ro, giữ K-201 dừng để kiểm tra rung và báo Tổng chỉ huy giàn (OIM); ghi đúng DEF-UNPLAN và tối ưu các giếng còn lại.",en:"Do not bypass without an approved override permit and risk assessment, keep K-201 down for vibration checks and inform the OIM; book DEF-UNPLAN and optimize the other wells."},shortcut:{vi:"Bypass liên động, chạy lại K-201 có người canh và ghi hao hụt theo kế hoạch.",en:"Bypass the trip, restart K-201 with a watchman and book the loss as planned."},wait:{vi:"Để trưởng ca tự quyết định, chờ ca sau hoàn thiện báo cáo.",en:"Let the shift supervisor decide and leave the report for the next shift."}},questions:{vi:["Vì sao sự cố K-201 là DEF-UNPLAN? Bằng chứng nào trong nhật ký và kế hoạch bảo dưỡng hỗ trợ kết luận?","Trình bày cách tính dầu hao hụt và rủi ro an toàn, pháp lý nếu bypass liên động rung cao khi chưa được phê duyệt."],en:["Why is the K-201 event DEF-UNPLAN? Which evidence in the logs and maintenance plan supports this?","Explain the deferred oil calculation and the safety and legal risk of bypassing the vibration trip without approval."]},hints:{vi:["Đối chiếu nhật ký cảnh báo với kế hoạch bảo dưỡng để biết sự cố có được lên kế hoạch hay không.","Chọn đúng phép thử còn hiệu lực, trừ nước rồi nhân thời gian dừng theo SOP mục 3.2.","Đọc lại SOP mục 4.2: mọi bypass hệ thống an toàn cần phiếu phê duyệt, đánh giá rủi ro và người có thẩm quyền."],en:["Match the alarm log with the maintenance plan to see whether the outage was planned.","Pick the valid well test, remove water, then apply the downtime per SOP 3.2.","Re-read SOP 4.2: any safety system bypass needs an approved permit, a risk assessment and the responsible authority."]},terminal:{system:"dcs-prod",settable:["DEFER_CAT","DEFER_BBL"],commands:[{cmd:"alarm log",out:{vi:"03:12 K-201 trip rung cao 11.2 mm/s; 03:14 W-12 mất khí gaslift, van an toàn đóng; 12:12 W-12 mở lại sau khi K-201 chạy lại.",en:"03:12 K-201 trip on high vibration 11.2 mm/s; 03:14 W-12 lost lift gas, safety valve closed; 12:12 W-12 reopened after K-201 restart."}},{cmd:"well test w-12",out:{vi:"02/10: chất lỏng 2600 bbl/ngày, ngậm nước 15% (đã bị thay thế). 25/10: chất lỏng 2300 bbl/ngày, ngậm nước 20% (hợp lệ).",en:"02/10: liquid 2600 bbl/d, water cut 15% (superseded). 25/10: liquid 2300 bbl/d, water cut 20% (valid)."}},{cmd:"maint plan k-201",out:{vi:"Không có lệnh công việc bảo dưỡng theo kế hoạch cho K-201 trong tháng 10; lần bảo dưỡng kế tiếp 15/12.",en:"No planned maintenance work order for K-201 in October; next planned maintenance on 15/12."}},{cmd:"vib trend k-201",out:{vi:"Rung ổ đỡ phía dẫn động tăng từ 4.5 lên 11.2 mm/s trong 6 giờ trước khi trip.",en:"Drive-end bearing vibration rose from 4.5 to 11.2 mm/s in the 6 hours before the trip."}},{cmd:"cat override.log",out:{vi:"03:40 trưởng ca yêu cầu bypass liên động rung cao K-201: chưa có phiếu phê duyệt, chưa có đánh giá rủi ro.",en:"03:40 shift supervisor requested a K-201 vibration trip bypass: no approved permit, no risk assessment."}}]}},learning:{summary:{vi:"Kỹ sư vận hành khai thác dầu khí giám sát giếng và hệ thống xử lý bề mặt hằng ngày: tối ưu lưu lượng, khai thác cơ học bằng gaslift, thử giếng, phân bổ sản lượng và theo dõi hao hụt. Nghề giữ cho sản lượng ổn định mà vẫn an toàn tuyệt đối, đòi hỏi hiểu vỉa, giếng, thiết bị và kỷ luật với hệ thống an toàn công nghệ.",en:"An oil and gas production operations engineer oversees wells and surface facilities every day: rate optimization, gas lift, well testing, production allocation and deferment tracking. The role keeps production stable while staying absolutely safe, and requires knowledge of reservoirs, wells, equipment and discipline with process safety systems."},responsibilities:{vi:["Theo dõi lưu lượng, áp suất, độ ngậm nước và GOR của từng giếng theo ca.","Lập lịch và kiểm tra chất lượng phép thử giếng, cập nhật tiềm năng giếng.","Tối ưu khí gaslift, côn tiết lưu và phối hợp với nhóm vỉa để tăng thu hồi.","Lập báo cáo sản lượng ngày, phân bổ sản lượng và phân loại hao hụt.","Tuân thủ giấy phép làm việc, quản lý thay đổi và quy trình bypass hệ thống an toàn."],en:["Monitor rates, pressures, water cut and GOR for each well every shift.","Schedule and quality-check well tests and update well potentials.","Optimize lift gas and chokes and work with reservoir engineers to improve recovery.","Prepare the daily production report, allocation and deferment classification.","Follow permit to work, management of change and safety system bypass procedures."]},competencies:[{name:{vi:"Phân tích giếng",en:"Well performance analysis"},desc:{vi:"Dùng đường IPR, VLP và phân tích nút để chẩn đoán và tối ưu giếng.",en:"Use IPR and VLP curves and nodal analysis to diagnose and optimize wells."}},{name:{vi:"Khai thác cơ học",en:"Artificial lift"},desc:{vi:"Vận hành và tối ưu gaslift, bơm điện chìm và xử lý mất ổn định dòng chảy.",en:"Operate and optimize gas lift and ESPs and handle flow instability."}},{name:{vi:"Số liệu sản lượng",en:"Production data"},desc:{vi:"Kiểm soát phép thử, phân bổ sản lượng và phân loại hao hụt chính xác.",en:"Control well tests, allocation and accurate deferment classification."}},{name:{vi:"An toàn công nghệ",en:"Process safety"},desc:{vi:"Tôn trọng liên động, chỉ bypass theo phiếu phê duyệt và đánh giá rủi ro.",en:"Respect trips and only bypass with an approved permit and risk assessment."}},{name:{vi:"Phối hợp đa ngành",en:"Cross-discipline coordination"},desc:{vi:"Làm việc với bảo dưỡng, vỉa, khoan và bờ để ra quyết định nhanh và an toàn.",en:"Work with maintenance, reservoir, drilling and onshore teams for fast and safe decisions."}}],knowledge:{vi:["Luật Dầu khí số 12/2022/QH15 và yêu cầu về báo cáo khai thác, an toàn dầu khí.","API RP 14C về phân tích, thiết kế, lắp đặt và thử nghiệm hệ thống an toàn cho thiết bị khai thác ngoài khơi.","IEC 61511 về hệ thống an toàn công nghệ và quản lý bypass, override.","Phân tích giếng: chỉ số năng suất (PI), đường IPR và VLP, gaslift, độ ngậm nước, GOR.","API MPMS về đo lường dầu khí và nguyên tắc phân bổ sản lượng từ đồng hồ thương mại về giếng."],en:["Petroleum Law No. 12/2022/QH15 and requirements on production reporting and petroleum safety.","API RP 14C on analysis, design, installation and testing of offshore production safety systems.","IEC 61511 on safety instrumented systems and bypass and override management.","Well analysis: productivity index (PI), IPR and VLP curves, gas lift, water cut and GOR.","API MPMS on petroleum measurement and allocation principles from fiscal meters to wells."]},tools:["Hệ thống điều khiển phân tán (DCS)","Phần mềm phân tích nút giếng","Hệ thống báo cáo sản lượng ngày","Bình tách thử giếng","Hệ thống giám sát rung","Hệ thống PTW và MOC điện tử"],kpis:{vi:["Hiệu suất khai thác: sản lượng thực trên tiềm năng giếng.","Tỷ lệ hao hụt ngoài kế hoạch trên tổng tiềm năng.","Tỷ lệ giếng có phép thử hợp lệ đúng chu kỳ.","Số bypass hệ thống an toàn quá hạn (mục tiêu bằng 0)."],en:["Production efficiency: actual output over well potential.","Unplanned deferment as a share of total potential.","Share of wells with a valid test within the required cycle.","Overdue safety system bypasses (target zero)."]},day:[{time:"06:00",vi:"Giao ca, đọc nhật ký cảnh báo đêm và trạng thái từng giếng.",en:"Shift handover, read the overnight alarm log and each well's status."},{time:"08:00",vi:"Họp sản xuất với bảo dưỡng và bờ, thống nhất ưu tiên trong ngày.",en:"Production meeting with maintenance and onshore to agree daily priorities."},{time:"10:00",vi:"Thử giếng qua bình tách thử, kiểm tra chất lượng số liệu.",en:"Test a well through the test separator and check data quality."},{time:"14:00",vi:"Tối ưu phân phối khí gaslift giữa các giếng theo đường cong đáp ứng.",en:"Optimize lift gas distribution across wells using response curves."},{time:"17:00",vi:"Lập báo cáo sản lượng ngày, phân loại hao hụt và gửi về bờ.",en:"Prepare the daily production report, classify deferment and send it onshore."}],mistakes:{vi:["Tính hao hụt trên lưu lượng chất lỏng tổng thay vì dầu thực đã trừ nước.","Dùng phép thử giếng cũ đã bị thay thế để ước tính tiềm năng.","Bypass liên động an toàn bằng miệng để chạy lại nhanh, không có phiếu và đánh giá rủi ro."],en:["Calculating deferment on gross liquid instead of net oil after water.","Using an old, superseded well test to estimate potential.","Bypassing a safety trip verbally to restart quickly, without a permit or risk assessment."]},career:[{vi:"Kỹ sư vận hành khai thác tập sự",en:"Graduate production engineer"},{vi:"Kỹ sư vận hành khai thác",en:"Production operations engineer"},{vi:"Kỹ sư khai thác chính / giám sát vận hành",en:"Senior production engineer / superintendent"},{vi:"Quản lý vận hành mỏ / Tổng chỉ huy giàn",en:"Field operations manager / OIM"}],glossary:[{term:"Water cut",vi:"Độ ngậm nước: tỷ lệ nước trong tổng lưu lượng chất lỏng khai thác.",en:"The fraction of water in the total produced liquid."},{term:"GOR",vi:"Tỷ số khí dầu: thể tích khí khai thác trên mỗi thùng dầu ở điều kiện chuẩn.",en:"Gas-oil ratio: produced gas volume per barrel of oil at standard conditions."},{term:"Gas lift",vi:"Khai thác bằng khí nâng: bơm khí vào cần khai thác để giảm tỷ trọng cột chất lỏng.",en:"Injecting gas into the tubing to lighten the fluid column and lift production."},{term:"Deferment",vi:"Hao hụt sản lượng: phần sản lượng tiềm năng không khai thác được do dừng hoặc hạn chế.",en:"Production potential not delivered because of outages or constraints."},{term:"Override",vi:"Vô hiệu hóa tạm thời một chức năng an toàn, chỉ được phép theo quy trình phê duyệt.",en:"Temporarily disabling a safety function, allowed only through an approval process."}],quiz:[{q:{vi:"Giếng có chất lỏng 1500 bbl/ngày, ngậm nước 40%, dừng 12 giờ. Dầu hao hụt là bao nhiêu?",en:"A well makes 1500 bbl/d liquid at 40% water cut and is down 12 hours. What is the deferred oil?"},options:{vi:["750 bbl","300 bbl","900 bbl","450 bbl"],en:["750 bbl","300 bbl","900 bbl","450 bbl"]},answer:3,explain:{vi:"1500 x (1 - 0.4) x 12 / 24 = 450 bbl dầu thực.",en:"1500 x (1 - 0.4) x 12 / 24 = 450 bbl of net oil."}},{q:{vi:"Máy nén trip bất ngờ, không có trong kế hoạch bảo dưỡng. Hao hụt được xếp loại nào?",en:"A compressor trips unexpectedly and is not in the maintenance plan. How is the deferment classed?"},options:{vi:["Theo kế hoạch","Ngoài kế hoạch","Do bên ngoài","Không tính hao hụt"],en:["Planned","Unplanned","External","Not counted"]},answer:1,explain:{vi:"Sự cố thiết bị không có trong kế hoạch bảo dưỡng được duyệt là hao hụt ngoài kế hoạch.",en:"Equipment failure outside the approved maintenance plan is unplanned deferment."}},{q:{vi:"Trưởng ca yêu cầu bypass liên động rung cao để chạy lại ngay. Phản ứng đúng là gì?",en:"The shift supervisor wants to bypass a high vibration trip to restart now. What is the right response?"},options:{vi:["Bypass vì đã có người canh","Bypass trong 2 giờ rồi bật lại","Chỉ bypass theo phiếu phê duyệt, đánh giá rủi ro và người có thẩm quyền","Tắt cả hệ thống cảnh báo"],en:["Bypass since someone is watching","Bypass for 2 hours then restore","Bypass only with an approved permit, risk assessment and the authority","Disable the whole alarm system"]},answer:2,explain:{vi:"Rung cao có thể dẫn tới hỏng hóc nghiêm trọng; bypass chỉ hợp lệ khi qua quy trình phê duyệt chính thức.",en:"High vibration can lead to severe failure; a bypass is valid only through the formal approval process."}},{q:{vi:"Khi tính tiềm năng giếng, nên dùng phép thử nào?",en:"Which well test should be used to estimate well potential?"},options:{vi:["Phép thử hợp lệ gần nhất","Phép thử có lưu lượng cao nhất","Phép thử đầu tiên của giếng","Bình quân mọi phép thử"],en:["The latest valid test","The test with the highest rate","The well's first test","The average of all tests"]},answer:0,explain:{vi:"Phép thử hợp lệ gần nhất phản ánh đúng trạng thái giếng; phép thử cũ đã bị thay thế không được dùng.",en:"The latest valid test reflects the current well state; superseded tests must not be used."}}]}},"KK-969":{scenario:{company:"Petralux Gas Processing",supervisor:{name:"Bùi Thanh Tùng",role:{vi:"Trưởng phòng An toàn Quy trình",en:"Process Safety Manager"}},ref_code:"HZ-5521",title:{vi:"IPL phải độc lập. SIL phải đủ.",en:"IPLs must be independent. SIL must suffice."},brief:{vi:"Bạn rà soát bảng LOPA HZ-5521 cho kịch bản quá áp bình tách V-310 do vòng điều khiển BPCS đóng nhầm van đầu ra (IEF 0.1/năm). Bản nháp ghi nhận van an toàn PSV-310 (PFD 0.01) và cảnh báo áp cao do chính bộ điều khiển BPCS đó phát (PFD 0.1). Xác suất bắt cháy 0.5, xác suất có người 0.3; TMEL 1E-6/năm. Sửa mức SIL và hệ số giảm rủi ro (RRF) yêu cầu cho SIF trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are reviewing LOPA worksheet HZ-5521 for overpressure of separator V-310 caused by a BPCS loop wrongly closing the outlet valve (IEF 0.1/yr). The draft credits relief valve PSV-310 (PFD 0.01) and a high pressure alarm raised by that same BPCS controller (PFD 0.1). Ignition probability 0.5, occupancy 0.3; TMEL 1E-6/yr. Correct the required SIL and risk reduction factor (RRF) for the SIF in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Biên bản HAZOP/LOPA đã phê duyệt · HZ-5521",en:"Approved HAZOP/LOPA record · HZ-5521"},fields:[{id:"SIL_REQ",label:{vi:"Mức SIL yêu cầu cho SIF",en:"Required SIF SIL"},initial:"SIL 1",expected:"SIL 2",choices:["SIL 1","SIL 2","SIL 3"],reference:"Biên bản LOPA đã phê duyệt",hint:{vi:"Xếp SIL theo dải RRF ở chế độ nhu cầu thấp của IEC 61511 sau khi loại các IPL không độc lập.",en:"Assign SIL from the IEC 61511 low-demand RRF bands after removing non-independent IPLs."}},{id:"RRF_REQ",label:{vi:"RRF yêu cầu của SIF",en:"Required SIF RRF"},initial:"15",expected:"150",reference:"Bảng tính LOPA HZ-5521",ref_value:{vi:"IEF 0.1; PSV 0.01; cảnh báo BPCS 0.1 (cùng vòng); bắt cháy 0.5; có người 0.3; TMEL 1E-6",en:"IEF 0.1; PSV 0.01; BPCS alarm 0.1 (same loop); ignition 0.5; occupancy 0.3; TMEL 1E-6"},hint:{vi:"Lớp bảo vệ dùng chung bộ điều khiển với sự kiện khởi đầu không được tính; chia tần suất còn lại cho TMEL.",en:"A layer sharing the controller with the initiating event cannot be credited; divide the remaining frequency by TMEL."}}],sop32:{vi:"Tần suất còn lại = IEF x tích PFD các IPL độc lập x hệ số điều kiện; RRF yêu cầu = tần suất còn lại / TMEL. Không ghi nhận IPL dùng chung cảm biến hay bộ điều khiển với sự kiện khởi đầu.",en:"Remaining frequency = IEF x product of independent IPL PFDs x conditional modifiers; required RRF = remaining frequency / TMEL. Never credit an IPL sharing a sensor or controller with the initiating event."},context:{label:"PHA / HZ-5521",metrics:[{label:{vi:"IEF (lần/năm)",en:"IEF (per year)"},value:"0.1"},{label:{vi:"PFD van PSV-310",en:"PSV-310 PFD"},value:"0.01"},{label:{vi:"Bắt cháy x có người",en:"Ignition x occupancy"},value:"0.5 x 0.3"},{label:{vi:"TMEL (lần/năm)",en:"TMEL (per year)"},value:"1E-6"}]},crisis:{vi:"Giám đốc dự án nhắn: “Giữ SIL 1 như bản nháp để dùng van hiện có, mua van đạt SIL 2 mất 14 tuần. Ký đóng khuyến nghị LOPA hôm nay cho kịp chạy thử, sau này nâng cấp sau.”",en:"The project director messages you: “Keep SIL 1 as drafted so we can use the existing valve, a SIL 2 valve takes 14 weeks. Sign off the LOPA recommendation today so we can start up, we will upgrade later.”"},options:{safe:{vi:"Giữ yêu cầu SIL 2 và không ký đóng khuyến nghị; báo cơ quan kỹ thuật an toàn quy trình bằng văn bản, đề xuất biện pháp bù trừ tạm thời qua MOC và chỉ chạy thử khi SIF được kiểm chứng.",en:"Keep the SIL 2 requirement and do not sign off; inform the process safety technical authority in writing, propose interim measures through MOC and start up only once the SIF is verified."},shortcut:{vi:"Ký đóng khuyến nghị với SIL 1 để chạy thử đúng hạn, nâng cấp van khi hàng về.",en:"Sign off at SIL 1 to start up on time and upgrade the valve when it arrives."},wait:{vi:"Không ký, không báo ai, để giám đốc dự án tự chịu trách nhiệm.",en:"Do not sign, tell no one and leave the project director to own the decision."}},questions:{vi:["Vì sao cảnh báo áp cao trên cùng BPCS không được tính là IPL? Dữ liệu nào cho ra RRF 150 và SIL 2?","Nếu buộc phải chạy thử trước khi có van mới, những biện pháp bù trừ và phê duyệt nào là hợp lệ?"],en:["Why can the high pressure alarm on the same BPCS not be credited as an IPL? Which data yields the corrected RRF and SIL?","If start-up must happen before the new valve arrives, which interim measures and approvals are acceptable?"]},hints:{vi:["Kiểm tra tính độc lập của từng IPL với nguyên nhân khởi đầu trước khi nhân PFD.","Tính tần suất còn lại theo SOP mục 3.2 rồi so RRF với dải SIL ở chế độ nhu cầu thấp.","Đọc lại SOP mục 4.2: không hạ SIL vì tiến độ hay chi phí; mọi sai lệch phải qua MOC và người có thẩm quyền."],en:["Check each IPL's independence from the initiating cause before multiplying PFDs.","Compute the remaining frequency per SOP 3.2, then compare the RRF with the low-demand SIL bands.","Re-read SOP 4.2: never lower a SIL for schedule or cost; any deviation must go through MOC and the authority."]}},learning:{summary:{vi:"Kỹ sư an toàn quy trình trong ngành năng lượng nhận diện, đánh giá và kiểm soát rủi ro cháy nổ, rò rỉ chất nguy hại tại nhà máy xử lý khí, lọc dầu, điện và kho chứa. Công cụ chính là HAZOP, LOPA, xác định và kiểm chứng SIL, phân tích hậu quả và quản lý thay đổi. Nghề đòi hỏi tư duy hệ thống, hiểu công nghệ và dũng cảm giữ chuẩn an toàn trước áp lực tiến độ.",en:"A process safety engineer in the energy sector identifies, assesses and controls fire, explosion and toxic release risks at gas plants, refineries, power plants and terminals. Core tools are HAZOP, LOPA, SIL determination and verification, consequence analysis and management of change. The role requires systems thinking, process knowledge and the courage to hold safety standards against schedule pressure."},responsibilities:{vi:["Tổ chức và làm thư ký kỹ thuật cho HAZOP, LOPA, rà soát an toàn thiết kế và vận hành.","Xác định SIL yêu cầu, kiểm chứng PFD của SIF và theo dõi chu kỳ thử định kỳ.","Phân tích hậu quả phát tán, cháy, nổ và đề xuất lớp bảo vệ, khoảng cách an toàn.","Quản lý khuyến nghị, MOC, rà soát an toàn trước khởi động (PSSR) và bypass hệ thống an toàn.","Điều tra sự cố, theo dõi chỉ số an toàn quy trình và đào tạo văn hóa an toàn."],en:["Facilitate and scribe HAZOP, LOPA and design and operations safety reviews.","Determine required SIL, verify SIF PFD and track proof test intervals.","Analyze dispersion, fire and explosion consequences and propose protection layers and spacing.","Manage recommendations, MOC, pre-startup safety reviews (PSSR) and safety system bypasses.","Investigate incidents, track process safety indicators and build safety culture."]},competencies:[{name:{vi:"Nhận diện mối nguy",en:"Hazard identification"},desc:{vi:"Dẫn dắt HAZOP bằng từ dẫn hướng, tìm nguyên nhân, hậu quả và biện pháp bảo vệ.",en:"Lead HAZOP with guidewords and find causes, consequences and safeguards."}},{name:{vi:"Đánh giá rủi ro định lượng",en:"Quantitative risk assessment"},desc:{vi:"Áp dụng LOPA, cây sự cố, cây sự kiện và tiêu chí rủi ro chấp nhận được.",en:"Apply LOPA, fault trees, event trees and tolerable risk criteria."}},{name:{vi:"An toàn chức năng",en:"Functional safety"},desc:{vi:"Xác định SIL, kiểm chứng kiến trúc, PFDavg và yêu cầu thử định kỳ theo IEC 61511.",en:"Determine SIL and verify architecture, PFDavg and proof testing per IEC 61511."}},{name:{vi:"Hiểu công nghệ quá trình",en:"Process knowledge"},desc:{vi:"Đọc P&ID, cân bằng vật chất, hiểu thiết bị áp lực, xả áp và hệ thống đuốc.",en:"Read P&IDs and mass balances and understand pressure equipment, relief and flare."}},{name:{vi:"Bản lĩnh an toàn",en:"Safety leadership"},desc:{vi:"Giữ yêu cầu an toàn trước áp lực chi phí, tiến độ và báo cáo minh bạch.",en:"Hold safety requirements against cost and schedule pressure and report transparently."}}],knowledge:{vi:["IEC 61511 và IEC 61508 về an toàn chức năng; dải RRF chế độ nhu cầu thấp: SIL 1 >10-100, SIL 2 >100-1000, SIL 3 >1000-10000.","Hướng dẫn LOPA của CCPS: sự kiện khởi đầu, IPL độc lập, hệ số điều kiện và quy tắc độc lập với BPCS.","IEC 61882 về áp dụng nghiên cứu HAZOP: nút, từ dẫn hướng, độ lệch, nguyên nhân và hậu quả.","API RP 521 về hệ thống xả áp, giảm áp và API RP 754 về chỉ số an toàn quy trình Tier 1, Tier 2.","Luật An toàn, vệ sinh lao động số 84/2015/QH13 và yêu cầu ứng cứu sự cố tại cơ sở năng lượng."],en:["IEC 61511 and IEC 61508 on functional safety; low-demand RRF bands: SIL 1 >10-100, SIL 2 >100-1000, SIL 3 >1000-10000.","CCPS LOPA guidance: initiating events, independent IPLs, conditional modifiers and BPCS independence rules.","IEC 61882 on HAZOP application: nodes, guidewords, deviations, causes and consequences.","API RP 521 on pressure relief and depressuring and API RP 754 on Tier 1 and Tier 2 process safety indicators.","Occupational Safety and Health Law No. 84/2015/QH13 and emergency response duties at energy facilities."]},tools:["Phần mềm HAZOP/LOPA","Phần mềm mô phỏng hậu quả phát tán, cháy nổ","Công cụ kiểm chứng SIL (PFDavg)","Bộ P&ID và ma trận cause & effect","Hệ thống quản lý MOC và khuyến nghị","Sổ đăng ký rủi ro"],kpis:{vi:["Tỷ lệ khuyến nghị HAZOP/LOPA đóng đúng hạn.","Số sự cố an toàn quy trình Tier 1 và Tier 2 theo API RP 754.","Tỷ lệ SIF được thử định kỳ đúng hạn.","Số bypass và override quá hạn (mục tiêu bằng 0)."],en:["Share of HAZOP/LOPA recommendations closed on time.","Tier 1 and Tier 2 process safety events per API RP 754.","Share of SIFs proof-tested on schedule.","Overdue bypasses and overrides (target zero)."]},day:[{time:"08:00",vi:"Xem báo cáo ca: các bypass đang hiệu lực, cảnh báo lặp lại và sự cố suýt xảy ra.",en:"Review the shift report: active bypasses, repeated alarms and near misses."},{time:"09:30",vi:"Dẫn dắt một phiên HAZOP cho nút bình tách và hệ thống xả áp.",en:"Lead a HAZOP session on the separator node and the relief system."},{time:"13:30",vi:"Tính LOPA, xác định SIL cho các kịch bản mới và cập nhật sổ rủi ro.",en:"Run LOPA, set SIL for new scenarios and update the risk register."},{time:"15:30",vi:"Rà soát hồ sơ MOC và PSSR trước khi cho phép khởi động thiết bị.",en:"Review MOC and PSSR packages before allowing equipment start-up."},{time:"17:00",vi:"Báo cáo tiến độ khuyến nghị và rủi ro tồn đọng cho ban giám đốc.",en:"Report recommendation progress and open risks to management."}],mistakes:{vi:["Tính cảnh báo BPCS là IPL khi sự kiện khởi đầu chính là lỗi của vòng BPCS đó.","Dùng hệ số điều kiện hai lần hoặc lấy PFD lạc quan không có căn cứ dữ liệu.","Ký đóng khuyến nghị khi biện pháp chưa thực hiện vì áp lực tiến độ."],en:["Crediting a BPCS alarm as an IPL when the initiating event is that BPCS loop failing.","Double-counting conditional modifiers or using optimistic PFDs without data.","Closing recommendations before actions are done because of schedule pressure."]},career:[{vi:"Kỹ sư an toàn quy trình tập sự",en:"Graduate process safety engineer"},{vi:"Kỹ sư an toàn quy trình",en:"Process safety engineer"},{vi:"Chuyên gia an toàn chức năng / trưởng nhóm PHA",en:"Functional safety specialist / PHA lead"},{vi:"Trưởng phòng an toàn quy trình / cơ quan kỹ thuật an toàn",en:"Process safety manager / technical authority"}],glossary:[{term:"LOPA",vi:"Phân tích lớp bảo vệ: đánh giá bán định lượng tần suất kịch bản sau các lớp bảo vệ độc lập.",en:"Layer of protection analysis: a semi-quantitative estimate of scenario frequency after independent layers."},{term:"IPL",vi:"Lớp bảo vệ độc lập: biện pháp có hiệu lực, kiểm chứng được và độc lập với nguyên nhân khởi đầu.",en:"Independent protection layer: effective, auditable and independent of the initiating cause."},{term:"SIF",vi:"Chức năng an toàn công nghệ gồm cảm biến, bộ logic và phần tử chấp hành đưa quá trình về trạng thái an toàn.",en:"Safety instrumented function: sensor, logic and final element that bring the process to a safe state."},{term:"RRF",vi:"Hệ số giảm rủi ro, bằng nghịch đảo của PFD trung bình.",en:"Risk reduction factor, the inverse of the average PFD."},{term:"TMEL",vi:"Mức tần suất sự kiện tối đa có thể chấp nhận cho một mức hậu quả.",en:"Target mitigated event likelihood, the tolerable frequency for a consequence level."}],quiz:[{q:{vi:"IEF 0.5/năm, một IPL độc lập PFD 0.1, TMEL 1E-5/năm, không có hệ số điều kiện. RRF yêu cầu của SIF?",en:"IEF 0.5/yr, one independent IPL with PFD 0.1, TMEL 1E-5/yr, no conditional modifiers. What RRF does the SIF need?"},options:{vi:["500","5000","50","50000"],en:["500","5000","50","50000"]},answer:1,explain:{vi:"0.5 x 0.1 = 0.05/năm; 0.05 / 1E-5 = 5000, tương ứng SIL 3.",en:"0.5 x 0.1 = 0.05/yr; 0.05 / 1E-5 = 5000, which is SIL 3."}},{q:{vi:"Sự kiện khởi đầu là lỗi vòng điều khiển BPCS. Cảnh báo phát từ cùng bộ điều khiển đó có được tính là IPL?",en:"The initiating event is a BPCS loop failure. Can an alarm from the same controller be credited as an IPL?"},options:{vi:["Có, PFD 0.1","Có nếu người vận hành giàu kinh nghiệm","Có nếu cảnh báo ưu tiên cao","Không, vì không độc lập với sự kiện khởi đầu"],en:["Yes, PFD 0.1","Yes if operators are experienced","Yes if the alarm is high priority","No, it is not independent of the initiating event"]},answer:3,explain:{vi:"IPL phải độc lập; cảnh báo trên chính vòng BPCS bị lỗi sẽ mất cùng lúc với nguyên nhân.",en:"IPLs must be independent; an alarm on the failed BPCS loop is lost with the cause."}},{q:{vi:"Giám đốc dự án yêu cầu ký đóng khuyến nghị SIL khi van đạt chuẩn chưa về. Bạn làm gì?",en:"The project director asks you to close a SIL recommendation before the compliant valve arrives. What do you do?"},options:{vi:["Từ chối, báo cơ quan kỹ thuật và đề xuất biện pháp tạm thời qua MOC","Ký vì sẽ nâng cấp sau","Ký với ghi chú nhỏ","Nhờ đồng nghiệp ký thay"],en:["Refuse, inform the technical authority and propose interim measures via MOC","Sign since it will be upgraded","Sign with a small note","Ask a colleague to sign"]},answer:0,explain:{vi:"Khuyến nghị chỉ được đóng khi đã thực hiện; sai lệch tạm thời phải được đánh giá và phê duyệt qua MOC.",en:"A recommendation closes only once done; temporary deviations must be assessed and approved via MOC."}},{q:{vi:"RRF yêu cầu bằng 400 tương ứng mức SIL nào ở chế độ nhu cầu thấp?",en:"A required RRF of 400 corresponds to which low-demand SIL?"},options:{vi:["SIL 1","SIL 3","SIL 2","SIL 4"],en:["SIL 1","SIL 3","SIL 2","SIL 4"]},answer:2,explain:{vi:"RRF lớn hơn 100 đến 1000 thuộc SIL 2 theo IEC 61511.",en:"An RRF above 100 up to 1000 is SIL 2 under IEC 61511."}}]}},"KK-970":{scenario:{company:"Chargio Mobility Hub",supervisor:{name:"Viên Thảo Nguyên",role:{vi:"Trưởng phòng Vận hành Mạng lưới Sạc",en:"Charging Network Operations Manager"}},ref_code:"EVC-4127",title:{vi:"Đúng chế độ sạc. Đủ công suất lưới.",en:"Right charging mode. Enough grid capacity."},brief:{vi:"Bạn hoàn thiện hồ sơ đăng ký đấu nối EVC-4127 cho trạm sạc ST-27 tại bãi xe một trung tâm thương mại: 6 trụ sạc nhanh DC 120 kW đầu nối CCS2 (bộ chỉnh lưu đặt trong trụ) và 10 trụ AC 11 kW; phụ tải phụ trợ 23 kW. Hệ số đồng thời DC 0.8, AC 0.6; hệ số công suất 0.95. Sửa chế độ sạc theo IEC 61851-1 của trụ DC và công suất đăng ký đấu nối (kVA) trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"You are completing grid connection application EVC-4127 for charging site ST-27 in a shopping mall car park: 6 DC fast chargers of 120 kW with CCS2 connectors (rectifier inside the charger) and 10 AC chargers of 11 kW; auxiliary load 23 kW. Diversity factor DC 0.8, AC 0.6; power factor 0.95. Correct the IEC 61851-1 charging mode of the DC units and the grid connection capacity (kVA) in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Thiết kế điện & thông số trụ sạc đã duyệt · EVC-4127",en:"Approved electrical design & charger specs · EVC-4127"},fields:[{id:"DC_MODE",label:{vi:"Chế độ sạc trụ DC (IEC 61851-1)",en:"DC charger mode (IEC 61851-1)"},initial:"MODE-3",expected:"MODE-4",choices:["MODE-2","MODE-3","MODE-4"],reference:"Bảng thông số kỹ thuật trụ sạc",hint:{vi:"Chế độ 3 cấp AC cho bộ sạc trên xe; khi bộ chỉnh lưu nằm trong trụ và cấp DC trực tiếp cho pin thì là chế độ khác.",en:"Mode 3 supplies AC to the on-board charger; when the rectifier sits in the unit and feeds DC to the battery, it is another mode."}},{id:"GRID_KVA",label:{vi:"Công suất đăng ký đấu nối (kVA)",en:"Grid connection capacity (kVA)"},initial:"665",expected:"700",reference:"Bảng tính phụ tải trạm sạc",ref_value:{vi:"6 x 120 kW DC (đồng thời 0.8); 10 x 11 kW AC (0.6); phụ trợ 23 kW; cos phi 0.95",en:"6 x 120 kW DC (diversity 0.8); 10 x 11 kW AC (0.6); auxiliary 23 kW; power factor 0.95"},hint:{vi:"Bản nháp mới dừng ở công suất tác dụng kW; công suất đăng ký với điện lực tính bằng kVA.",en:"The draft stops at real power in kW; the capacity requested from the utility is in kVA."}}],sop32:{vi:"Công suất đăng ký (kVA) = (số trụ DC x công suất x hệ số đồng thời DC + số trụ AC x công suất x hệ số đồng thời AC + phụ tải phụ trợ) / hệ số công suất.",en:"Requested capacity (kVA) = (DC units x rating x DC diversity + AC units x rating x AC diversity + auxiliary load) / power factor."},context:{label:"CPMS / EVC-4127",metrics:[{label:{vi:"Trụ sạc DC",en:"DC chargers"},value:"6 x 120 kW"},{label:{vi:"Trụ sạc AC",en:"AC chargers"},value:"10 x 11 kW"},{label:{vi:"Phụ tải phụ trợ",en:"Auxiliary load"},value:"23 kW"},{label:{vi:"Hệ số công suất",en:"Power factor"},value:"0.95"}]},crisis:{vi:"Nhà thầu nhắn: “Đấu tạm trạm sạc vào tủ điện tòa nhà để khai trương thứ Bảy, chưa cần chờ điện lực nghiệm thu hay thử RCD. Chủ đầu tư đã mời báo chí rồi, lùi lịch là mất mặt.”",en:"The contractor messages you: “Hook the chargers temporarily onto the building switchboard to open on Saturday, no need to wait for utility acceptance or RCD tests. The owner has invited the press, postponing would be embarrassing.”"},options:{safe:{vi:"Không cấp điện khi chưa thử nghiệm, nghiệm thu và được điện lực chấp thuận; báo trưởng phòng và chủ đầu tư bằng văn bản, đề xuất lịch khai trương theo tiến độ nghiệm thu.",en:"Do not energize before testing, acceptance and utility approval; inform the manager and owner in writing and propose an opening date aligned with acceptance."},shortcut:{vi:"Đấu tạm vào tủ tòa nhà để kịp khai trương, làm thủ tục nghiệm thu bổ sung sau.",en:"Connect temporarily to the building switchboard to open on time and complete acceptance later."},wait:{vi:"Không phản hồi, để nhà thầu và chủ đầu tư tự xử lý.",en:"Do not reply and let the contractor and owner sort it out."}},questions:{vi:["Vì sao trụ DC 120 kW thuộc MODE-4? Dữ liệu nào cho ra công suất đăng ký 700 kVA?","Đấu tạm vào tủ tòa nhà khi chưa nghiệm thu gây rủi ro gì về an toàn điện, cháy nổ và pháp lý? Bạn đề xuất phương án nào?"],en:["Why are the 120 kW DC units MODE-4? Which data gives the corrected connection capacity?","What electrical, fire and legal risks come from a temporary hookup before acceptance? What alternative do you propose?"]},hints:{vi:["Xác định bộ chuyển đổi AC/DC nằm ở đâu: trên xe hay trong trụ sạc.","Cộng phụ tải có tính hệ số đồng thời rồi chia hệ số công suất theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không cấp điện trước nghiệm thu; báo cáo áp lực và đề xuất lịch hợp lệ."],en:["Find where the AC/DC converter sits: on the vehicle or inside the charger.","Add the diversified loads, then divide by power factor per SOP 3.2.","Re-read SOP 4.2: never energize before acceptance; report the pressure and propose a compliant schedule."]}},learning:{summary:{vi:"Chuyên viên hạ tầng trạm sạc xe điện quy hoạch vị trí, tính toán phụ tải và đấu nối, giám sát lắp đặt, nghiệm thu và vận hành mạng lưới trụ sạc AC, DC. Nghề bảo đảm trạm sạc an toàn, sẵn sàng và hiệu quả kinh tế, đòi hỏi hiểu điện hạ áp, tiêu chuẩn sạc, giao thức OCPP, an toàn cháy và kỹ năng điều phối nhiều bên.",en:"An EV charging infrastructure specialist plans sites, sizes loads and grid connections, supervises installation, commissioning and operation of AC and DC charger networks. The role keeps sites safe, available and economically sound, and requires low-voltage electrical knowledge, charging standards, the OCPP protocol, fire safety and multi-party coordination."},responsibilities:{vi:["Khảo sát, chọn vị trí và dự báo nhu cầu sạc theo lưu lượng xe và hành vi người dùng.","Tính phụ tải, hệ số đồng thời, công suất đấu nối và phương án quản lý tải động.","Lập hồ sơ đấu nối, phối hợp điện lực, nhà thầu và chủ mặt bằng trong thi công.","Nghiệm thu trụ sạc: thử RCD, nối đất, giao tiếp OCPP và phiên sạc thực tế.","Giám sát vận hành, xử lý sự cố, bảo trì phòng ngừa và báo cáo hiệu suất mạng lưới."],en:["Survey and select sites and forecast charging demand from traffic and user behavior.","Calculate loads, diversity, connection capacity and dynamic load management.","Prepare connection applications and coordinate the utility, contractors and landlords.","Commission chargers: RCD and earthing tests, OCPP communication and live sessions.","Monitor operations, handle faults, run preventive maintenance and report network performance."]},competencies:[{name:{vi:"Điện hạ áp & đấu nối",en:"Low-voltage & grid connection"},desc:{vi:"Tính phụ tải, chọn cáp, bảo vệ, nối đất và làm việc với yêu cầu của điện lực.",en:"Size loads, cables, protection and earthing and meet utility requirements."}},{name:{vi:"Tiêu chuẩn sạc",en:"Charging standards"},desc:{vi:"Hiểu chế độ sạc, chuẩn đầu nối, giao tiếp xe với trụ và trụ với hệ thống quản lý.",en:"Understand charging modes, connector standards, vehicle and back-end communication."}},{name:{vi:"Điều phối vận hành",en:"Operations coordination"},desc:{vi:"Lập kế hoạch thi công, nghiệm thu, bảo trì và điều phối đội kỹ thuật hiện trường.",en:"Plan installation, commissioning and maintenance and coordinate field teams."}},{name:{vi:"Phân tích dữ liệu sạc",en:"Charging data analysis"},desc:{vi:"Theo dõi uptime, tỷ lệ phiên thành công, hệ số sử dụng và đề xuất tối ưu.",en:"Track uptime, session success and utilization and propose improvements."}},{name:{vi:"An toàn & tuân thủ",en:"Safety & compliance"},desc:{vi:"Không cấp điện khi chưa nghiệm thu, tuân thủ an toàn điện và an toàn cháy bãi xe.",en:"Never energize before acceptance and comply with electrical and car park fire safety."}}],knowledge:{vi:["IEC 61851-1 về yêu cầu chung của hệ thống sạc dẫn điện cho xe điện và các chế độ sạc 1-4.","IEC 62196 về phích, ổ cắm và đầu nối sạc: Type 2 cho AC, CCS2 (cấu hình FF) cho DC.","IEC 60364-7-722 về lắp đặt hạ áp cấp điện cho xe điện: RCD, bảo vệ quá dòng, nối đất.","OCPP 1.6J và 2.0.1 cho giao tiếp trụ với hệ thống quản lý; ISO 15118 cho giao tiếp xe với trụ.","QCVN 06:2022/BXD về an toàn cháy cho nhà và công trình, áp dụng khi bố trí trạm sạc trong bãi xe."],en:["IEC 61851-1 general requirements for EV conductive charging systems and charging modes 1-4.","IEC 62196 plugs, sockets and couplers: Type 2 for AC, CCS2 (configuration FF) for DC.","IEC 60364-7-722 low-voltage installations supplying electric vehicles: RCD, overcurrent protection, earthing.","OCPP 1.6J and 2.0.1 for charger to back-end communication; ISO 15118 for vehicle to charger communication.","QCVN 06:2022/BXD on fire safety of buildings, applied when placing chargers in car parks."]},tools:["Hệ thống quản lý điểm sạc (CPMS) qua OCPP","Máy thử trụ sạc và thử RCD","Máy phân tích chất lượng điện","Phần mềm thiết kế điện hạ áp","Bản đồ GIS mạng lưới trạm","Công cụ dự báo nhu cầu sạc"],kpis:{vi:["Thời gian sẵn sàng hoạt động của trụ sạc (uptime %).","Tỷ lệ phiên sạc thành công ngay lần đầu.","Hệ số sử dụng trụ sạc (giờ sạc mỗi ngày).","Thời gian trung bình khắc phục sự cố (MTTR)."],en:["Charger uptime (%).","First-attempt charging session success rate.","Charger utilization (charging hours per day).","Mean time to repair (MTTR)."]},day:[{time:"07:30",vi:"Xem bảng điều khiển CPMS: trụ ngoại tuyến, lỗi phiên sạc và cảnh báo nhiệt.",en:"Check the CPMS dashboard: offline chargers, failed sessions and thermal alarms."},{time:"09:00",vi:"Điều phối đội hiện trường xử lý trụ lỗi theo mức ưu tiên.",en:"Dispatch field crews to faulty chargers by priority."},{time:"11:00",vi:"Làm việc với điện lực về hồ sơ đấu nối và lịch nghiệm thu trạm mới.",en:"Work with the utility on connection files and acceptance dates for new sites."},{time:"14:00",vi:"Giám sát nghiệm thu: thử RCD, điện trở nối đất và phiên sạc thực tế.",en:"Supervise commissioning: RCD tests, earthing resistance and live sessions."},{time:"16:30",vi:"Phân tích hệ số sử dụng, đề xuất cấu hình quản lý tải và báo cáo tuần.",en:"Analyze utilization, propose load management settings and write the weekly report."}],mistakes:{vi:["Đăng ký công suất theo kW mà quên chia hệ số công suất, dẫn tới thiếu dung lượng máy biến áp.","Cộng công suất định mức của mọi trụ mà không áp dụng hệ số đồng thời hoặc quản lý tải động.","Cấp điện tạm trước khi thử RCD, nối đất và được điện lực chấp thuận."],en:["Requesting capacity in kW without dividing by power factor, leaving the transformer undersized.","Adding every charger's rating without diversity or dynamic load management.","Energizing temporarily before RCD and earthing tests and utility approval."]},career:[{vi:"Kỹ thuật viên lắp đặt và bảo trì trụ sạc",en:"Charger installation and maintenance technician"},{vi:"Chuyên viên hạ tầng trạm sạc",en:"EV charging infrastructure specialist"},{vi:"Trưởng nhóm triển khai và vận hành mạng lưới sạc",en:"Charging network deployment and operations lead"},{vi:"Giám đốc hạ tầng di chuyển điện",en:"E-mobility infrastructure director"}],glossary:[{term:"Mode 4",vi:"Chế độ sạc DC với bộ sạc đặt ngoài xe, cáp cố định trên trụ, dùng cho sạc nhanh.",en:"DC charging with an off-board charger and a tethered cable, used for fast charging."},{term:"CCS2",vi:"Hệ thống sạc kết hợp dùng chung cổng Type 2 với hai chân DC, phổ biến tại châu Âu và nhiều thị trường châu Á.",en:"Combined charging system sharing the Type 2 inlet with two DC pins, common in Europe and many Asian markets."},{term:"OCPP",vi:"Giao thức mở cho trụ sạc trao đổi dữ liệu với hệ thống quản lý điểm sạc.",en:"Open protocol for chargers to exchange data with the charge point management system."},{term:"DLM",vi:"Quản lý tải động: phân bổ công suất giữa các trụ để không vượt công suất đấu nối.",en:"Dynamic load management: sharing power across chargers within the connection limit."},{term:"Diversity factor",vi:"Hệ số đồng thời: tỷ lệ công suất thực tế cùng lúc so với tổng công suất định mức.",en:"The ratio of simultaneous actual demand to the total rated load."}],quiz:[{q:{vi:"4 trụ DC 60 kW, hệ số đồng thời 0.75, phụ trợ 10 kW, hệ số công suất 0.95. Công suất đăng ký là bao nhiêu?",en:"4 DC chargers of 60 kW, diversity 0.75, auxiliary 10 kW, power factor 0.95. What capacity should be requested?"},options:{vi:["240 kVA","190 kVA","200 kVA","263 kVA"],en:["240 kVA","190 kVA","200 kVA","263 kVA"]},answer:2,explain:{vi:"Công suất đăng ký = (4 x 60 x 0.75 + 10) / 0.95 = 190 / 0.95 = 200 kVA.",en:"Requested capacity = (4 x 60 x 0.75 + 10) / 0.95 = 190 / 0.95 = 200 kVA."}},{q:{vi:"Trụ sạc có bộ chỉnh lưu bên trong, cấp DC trực tiếp cho pin xe thuộc chế độ nào theo IEC 61851-1?",en:"A charger with an internal rectifier feeding DC directly to the battery is which IEC 61851-1 mode?"},options:{vi:["Mode 1","Mode 2","Mode 3","Mode 4"],en:["Mode 1","Mode 2","Mode 3","Mode 4"]},answer:3,explain:{vi:"Mode 4 là sạc DC với bộ sạc ngoài xe; Mode 3 cấp AC qua trụ chuyên dụng cho bộ sạc trên xe.",en:"Mode 4 is DC charging with an off-board charger; Mode 3 supplies AC through a dedicated unit to the on-board charger."}},{q:{vi:"Nhà thầu đề nghị đấu tạm trụ sạc vào tủ tòa nhà để kịp khai trương. Bạn làm gì?",en:"The contractor proposes a temporary hookup to the building switchboard to open on time. What do you do?"},options:{vi:["Từ chối, báo cáo bằng văn bản và đề xuất lịch theo tiến độ nghiệm thu","Đồng ý nếu chỉ chạy hai trụ","Đồng ý và thử RCD sau","Để nhà thầu tự quyết"],en:["Refuse, report in writing and propose a schedule tied to acceptance","Agree if only two chargers run","Agree and test RCDs later","Let the contractor decide"]},answer:0,explain:{vi:"Cấp điện khi chưa nghiệm thu có thể gây điện giật, cháy và vi phạm hợp đồng đấu nối.",en:"Energizing before acceptance risks electric shock, fire and a breach of the connection agreement."}},{q:{vi:"OCPP dùng để làm gì?",en:"What is OCPP used for?"},options:{vi:["Đo điện trở nối đất","Kết nối trụ sạc với hệ thống quản lý điểm sạc","Tính hệ số công suất","Kiểm tra pin xe"],en:["Measuring earthing resistance","Connecting chargers to the charge point management system","Calculating power factor","Testing the vehicle battery"]},answer:1,explain:{vi:"OCPP là giao thức mở giữa trụ sạc và hệ thống quản lý: phiên sạc, giá, giám sát và cập nhật từ xa.",en:"OCPP is the open protocol between chargers and the back-end: sessions, tariffs, monitoring and remote updates."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(14)})(window.KKR);
